recortes.texto:
/* MM-C · C0 (11/10, a 6.ª sessão): o que o Mestre MOSTROU na conversa — as
   últimas falas dele, para o alvo do golpe sair da prosa ("ataco o cão sem
   pelo") e para o veto da luta que só a prosa começou. E a frase anterior
   do jogador, para o "pago as sete fichas" herdar o item do "quanto é".
   Leem `mensagensRef`, que já guarda tudo isto: não é estado novo, nem save. */
const LEITURA_DA_CONVERSA = { falasDoMestre: 2 };

/* decodifica escapes (\n, \", \t...) de um pedaço de string JSON */
/* parsing de resposta extraído para ./json.js (v8.6) */

/* ---------------- A JANELA DE HISTÓRICO (v9.105 → v9.162) ----------------
   Eram 18 turnos, depois 30. O NÚMERO estava certo; o CORTE estava
   errado: `slice(-30)` desliza uma mensagem por turno, o começo da
   janela muda, e o provedor cobra o histórico inteiro cheio, todo
   turno — a serra que o /custo denunciava. A conta e o porquê moram
   em janela.js: âncora fixa, salto raro, prefixo vivo. */

async function chamarMestre(system, historico) {
  /* histórico no formato Messages API, recortado pela janela ancorada (janela.js). Teto 3600: com 2600 o JSON truncava; é rede, não meta —
     o tamanho pede-se na etiqueta do pedido (escuta.js, 11.ª sessão). O turno leva a ficha do cache explícito; o reforço lá embaixo
     não (a mensagem a mais faria o servidor reescrever o cache por um pedido que não volta). */
  /* O PEDIDO NA ORDEM DO CACHE (v9.465): o system sai daqui igual a campanha
     inteira, e o que vira a cada turno (as regras da cena aberta e o ESTADO)
     desce para a mensagem do turno, antes do rodapé. A conta e o porquê
     moram em prompt.js. Se a arrumação estourar, o pedido vai como vinha. */
  let pedido = { system, messages: janelaAncorada(historico) };
  try { pedido = pedidoNaOrdemDoCache(system, pedido.messages); } catch (e) { calou("o pedido na ordem do cache", e); }
  let texto = await chamarModelo(pedido.system, pedido.messages, 3600, "json", "narrador", true);
  let resp = extrairJSON(texto);
  /* REDE DE SEGURANÇA (v7.0.2): se veio JSON válido mas SEM narrativa (o "…"
     na tela), tenta UMA segunda vez com um empurrão explícito antes de
     desistir. */
  if (!resp.narrativa || resp.narrativa === "…" || resp.narrativa.startsWith("O Mestre hesita")) {
    /* o reforço vai DEPOIS do pedido já arrumado: o prefixo é o da primeira
       tentativa inteira, e sai do cache quase todo */
    const reforco = [...pedido.messages, { role: "user", content: "[SISTEMA] Sua resposta anterior chegou sem o campo \"narrativa\". Responda de novo, em JSON, com \"narrativa\" SEMPRE preenchida (é o texto que o jogador lê)." }];
    texto = await chamarModelo(pedido.system, reforco, 3600, "json");
    const resp2 = extrairJSON(texto);
    if (resp2.narrativa && resp2.narrativa !== "…" && !resp2.narrativa.startsWith("O Mestre hesita")) {
      /* mantém as mudanças da primeira resposta se a segunda não trouxer */
      if (!resp2.mudancas && resp.mudancas) resp2.mudancas = resp.mudancas;
      resp = resp2;
    }
    /* MM15 (3): nem a segunda escrita trouxe narrativa — antes disto o
       turno CONTAVA com a frase de recurso na tela (o "…", ou "O Mestre
       hesita…"), uma falha de ligação vestida de sucesso: o relógio
       andava e a fala do Mestre era, na verdade, uma instrução de botão.
       Agora é o próprio Mestre que cala, pela classe que já sabe
       reconhecer este texto (`provedor_caiu`, em guardado.js). */
    if (narrativaFaltou(resp)) throw new Error(MOTIVO_SEM_NARRATIVA);
  }
  /* A FALA DO HERÓI É DO JOGADOR (11.ª sessão: o Mestre a escreveu em 16 de 62) — só sai o que é seguro; a régua mora em fala-do-heroi.js */
  try { const ultima = pedido.messages[pedido.messages.length - 1]; const podada = semFalaInventada(resp.narrativa, ultima && ultima.content); if (podada.cortadas.length) resp = { ...resp, narrativa: podada.narrativa }; } catch (e) { calou("a fala do herói", e); }
  return resp;
}

/* 06/10 (a luz e a sombra): as tochas que há para acender — as da
   masmorra lá dentro, as da mochila cá fora — e o mapa de luz da luta,
   refeito a cada pergunta dos mesmos refs (nunca vai ao save; o que vai é
   `combate.tochaDoHeroi`, campo novo e opcional). Null fora da luta, e
   null se estourar: o veredito volta à regra de antes. */
const tochasAgora = () => {
  const mm = masmorraRef.current;
  if (mm && !mm.encerrada) return Math.max(0, Number(mm.tochas) || 0);
  return Math.max(0, Number(((fichaViva() || {}).suprimentos || {}).tochas) || 0);
};

const luzDaLutaAgora = (comb) => {
  try {
    const c = comb || combateRef.current;
    if (!c) return null;
    const mm = masmorraRef.current;
    return luzDaLuta({
      grade: c.grade, heroi: c.heroi, aliados: c.aliados || [], inimigos: c.inimigos || [],
      tochaDoHeroi: c.tochaDoHeroi, tochas: tochasAgora(), emMasmorra: !!(mm && !mm.encerrada),
      noite: ehNoite(minutoRef.current), clima: (climaRef.current && climaRef.current.rotulo) || "",
      pers: fichaViva(),
    });
  } catch (e) { calou("a luz da luta", e); return null; }
};

const mudarFicha = (fn) => {
  const base = personagemRef.current || personagem;
  if (!base) return base;
  const novo = typeof fn === "function" ? fn(base) : fn;
  if (!novo) return base;
  personagemRef.current = novo;
  setPersonagem(novo);
  return novo;
};

/* 9.ª sessão (v9.433): a palavra do mundo para a moeda, para o preço que vai à pauta dizer a unidade
   — o Mestre vendia em "marcos" num mundo de moedas. 20/10: UM nome só por campanha (`nomeDaMoeda`),
   o mesmo da linha ECONOMIA do pedido; o léxico que chega tarde não o troca, e sem léxico é "moedas". */
const moedaDoMundo = () => { try { return nomeDaMoeda((mundoAtual() || {}).lexico); } catch (e) { calou("a moeda do mundo", e); return ""; } };

/* MM8c-2: o contexto e os nomes do elenco desta campanha — a gente que
   PESA na narração (resumoCenaPrompt, resumoNPCsParaPrompt, o cânone),
   não a lista para povoar (essa é `elencoParaPovoar`, mais abaixo). */
const contextoDoElenco = () => ({ genero: generoMundo(), molde: moldeMundo(), lex: (mundoAtual() || {}).lexico, espinha: espinhaRef.current, guildas: guildasRef.current, base: baseMundoRef.current, estado: elencoSaveRef.current, npcs: npcsRef.current });

/* MM-C C1: o núcleo desta campanha, memorizado pelo que o muda — o mesmo
   critério do cache do elenco (identidade dos refs) mais o companheiro,
   o antecedente e a reviravolta eleita. Recalcular a cada turno daria o
   mesmo núcleo pelo dobro do preço. */
const nucleoAgora = () => {
  const pers = personagemRef.current || personagem || {};
  const semente = sementeMundo(), mapa = mapaRef.current, ctx = contextoDoElenco();
  const comp = (pers.grupo || []).find((g) => g && g.nome && !g.invocada) || {};
  const rv = reviravoltaRef.current || null;
  const chave = [comp.nome || "", comp.conceito || "", comp.ligacao || "", pers.antecedente || "", (rv && rv.forma) || "", (rv && rv.alvo) || ""].join("|");
  const c = nucleoCacheRef.current;
  if (c && c.semente === semente && c.mapa === mapa && c.espinha === ctx.espinha && c.guildas === ctx.guildas && c.base === ctx.base && c.estado === ctx.estado && c.chave === chave) return c.nucleo;
  const nucleo = nucleoDaCampanha(semente, mapa, { ...ctx, grupo: pers.grupo || [], antecedente: pers.antecedente || "", reviravolta: rv && rv.forma ? { forma: rv.forma, alvo: rv.alvo } : null });
  nucleoCacheRef.current = { semente, mapa, espinha: ctx.espinha, guildas: ctx.guildas, base: ctx.base, estado: ctx.estado, chave, nucleo };
  return nucleo;
};

/* quem do núcleo está em cena: citado nas duas últimas falas do Mestre
   (pelo nome inteiro ou pelo primeiro, como o Mestre o chama) ou a andar
   no grupo. O registo de NPCs não basta: o elo e o vilão podem ainda não
   estar lá quando o Mestre já os pôs a falar. */
const nucleoEmCena = (nucleo) => {
  const sem = (x) => String(x == null ? "" : x).toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "");
  const fala = " " + sem((mensagensRef.current || []).filter((m) => m && m.autor === "mestre").slice(-2).map((m) => m.texto).join(" ")).replace(/[^a-z0-9]+/g, " ") + " ";
  const grupo = ((personagemRef.current || personagem || {}).grupo || []).filter((g) => g && g.nome && !g.invocada).map((g) => sem(g.nome));
  const out = [];
  for (const p of ((nucleo && nucleo.pessoas) || [])) {
    if (!p || !p.nome) continue;
    const inteiro = sem(String(p.nome).split(",")[0]).replace(/[^a-z0-9]+/g, " ").trim();
    const prim = inteiro.split(" ")[0] || "";
    const citado = (inteiro && fala.includes(" " + inteiro + " ")) || (prim.length >= 3 && fala.includes(" " + prim + " "));
    if (citado || grupo.includes(sem(p.nome))) out.push(p.nome);
  }
  return out;
};

/* MM-C C2: as subtramas do núcleo, memorizadas pelo próprio núcleo (que
   nucleoAgora já memoriza pelo que o muda). O elenco do mundo dá as casas. */
const subtramasAgora = (nucleo) => {
  const c = subtramasCacheRef.current;
  if (c && c.nucleo === nucleo) return c.lista;
  const semente = sementeMundo();
  let elenco = null;
  try { elenco = elencoDoMundo(semente, mapaRef.current, contextoDoElenco()); } catch (e) { calou("o elenco das subtramas", e); }
  const lista = subtramasDoNucleo(nucleo, { semente, espinha: espinhaRef.current, elenco });
  subtramasCacheRef.current = { nucleo, elenco, lista };
  return lista;
};

/* o contexto do coração neste instante — o mesmo para o turno, para a tela
   e para o clique. A máscara do aliado que já caiu (reviravoltas.js) vai
   em `reveladas`, com o ato em que caiu, para a do elo nunca cair no mesmo. */
/* 13/10 (v9.461, LONGE_DA_HISTORIA): quem esta longe e quem o registo SABE
   aqui — a mesma conta do EM CENA. O coracao (QUEM CARREGA) e o QUEM E
   leem-na para nao trazer a resposta quem a historia sabe noutra cidade. */
const elencoDoCoracao = () => {
  const grupo = ((personagemRef.current || personagem || {}).grupo) || [];
  try {
    const el = elencoDaCena(npcsRef.current, cidadeAtualRef.current, mapaRef.current, { comGrupo: grupo, masmorra: masmorraRef.current }) || {};
    return { longe: el.longe || [], presentes: el.aqui || [], grupo };
  } catch (e) { calou("quem está longe, para o coração", e); return { longe: [], presentes: [], grupo }; }
};

/* a cidade onde o heroi ESTA, para o coracao e para o QUEM E: vazia em
   viagem e na masmorra aberta */
const cidadeDoCoracao = () => (jornadaRef.current || (masmorraRef.current && !masmorraRef.current.encerrada)) ? "" : (cidadeAtualRef.current || "");

const contextoDoCoracao = (nucleo, extra) => {
  const esp = espinhaRef.current || {};
  const lista = subtramasAgora(nucleo);
  const ato = (historiaRef.current || {}).etapa || 0;
  const mortos = Object.values(npcsRef.current || {}).filter((n) => n && n.nome && String(n.status || "").toLowerCase() === "morto").map((n) => n.nome);
  let reveladas = [];
  try {
    const rv = reviravoltaRef.current;
    const mascara = ((nucleo && nucleo.pessoas) || []).find((x) => x && x.papel !== "elo" && x.revelaNoAto != null);
    if (rv && rv.revelada && mascara) {
      const k = (esp.atos || []).findIndex((a) => { const ms = ((a && a.marcos) || []).filter(Boolean); const f = ms.find((m) => m.batida && m.batida.fecho) || ms[ms.length - 1]; return !!(f && f.feito && Number(f.dia) >= (rv.reveladaEm || 0)); });
      reveladas = [{ nome: mascara.nome, ato: k >= 0 ? k : ato }];
    }
  } catch (e) { calou("a máscara que já caiu", e); }
  return { semente: sementeMundo(), espinha: esp, elenco: (subtramasCacheRef.current || {}).elenco || null, dia: diaRef.current, ato, turno: turnoDeRegistroRef.current + 1, emCena: nucleoEmCena(nucleo), ultimas: (coracaoRitmoRef.current || {}).ultimas || {}, luta: !!combateRef.current, mortos, reveladas, subtramas: lista, frase: "", maoDoVilao: false,
    /* 9.ª sessão (v9.434): a cidade onde o herói ESTÁ — a porta do elo
       (subtramas.js, PORTA_DO_ELO) só o traz quando é a dele. Em viagem e
       na masmorra aberta vai vazia: o elo não aparece na estrada. */
    cidade: cidadeDoCoracao(),
    ...elencoDoCoracao(),
    ...(extra || {}) };
};

const nomesDoElenco = () => {
  try {
    const semente = sementeMundo(), mapa = mapaRef.current, ctx = contextoDoElenco();
    const c = elencoCacheRef.current;
    if (c && c.semente === semente && c.mapa === mapa && c.espinha === ctx.espinha && c.guildas === ctx.guildas && c.base === ctx.base && c.estado === ctx.estado) return c.nomes;
    const nomes = elencoDoMundo(semente, mapa, ctx).pessoas.map((p) => p.nome);
    elencoCacheRef.current = { semente, mapa, espinha: ctx.espinha, guildas: ctx.guildas, base: ctx.base, estado: ctx.estado, nomes };
    return nomes;
  } catch (e) { calou("nomesDoElenco", e); return []; }
};

/* v9.40: a FORMA do mundo desta campanha. Todo gerador que fala de lugar
   recebe isto ao lado do gênero — um decide o sabor, o outro a forma. */
const moldeMundo = () => moldePorId((mundoAtual() && mundoAtual().molde) || MOLDE_PADRAO);

/* O que o Mestre recebe sobre o cosmos: regras só após o despertar (custo zero antes) */
const infoDivindade = () => {
  const dv = divindadeRef.current;
  if (!dv || !dv.despertar) return "";
  const fe = resumoFePrompt(mapaRef.current, devocaoRef.current, dv);
  return `${DIVINDADE_PROMPT}\n${CAMINHOS_PROMPT}\n${DEVOCAO_PROMPT}\nEstado atual do jogador: ${resumoAscensao(dv, 0)}${dv.panteao.length ? `\nPanteão conhecido: ${dv.panteao.map((d) => `${d.icone} ${d.nome} ${d.dominio} — GD ${d.gd} (${tituloDe(d.gd)}), culto: ${d.culto}`).join("; ")}.` : ""}${fe ? `\n${fe}` : ""}`;
};

/* A cidade sob os pés, resolvida uma vez. Devolve null fora de cidade. */
/* (Fase T, trilha A) a cidade no mapa é do motor (aCidadeSobOsPes, src/motor/tempo-do-turno.js) */
const cidadeSobOsPes = () => aCidadeSobOsPes({ cidadeAtual: cidadeAtualRef.current, mapa: mapaRef.current });

/* Todo lugar a que se pode ir daqui a pé: os locais de dentro dos muros, o
   cinturão de fora, e — quando o herói já está num local — os cômodos DELE.

   Os cômodos só entram quando se está no prédio de propósito: "subo para o
   quarto" na praça não quer dizer nada, e a mesma frase dentro da taverna
   quer dizer tudo. Um quarto é um lugar do prédio, não da cidade. */
const lugaresDaqui = () => {
  const cid = cidadeSobOsPes();
  if (!cid) return [];
  const dentro = locaisDaCidade(sementeMundo(), cid, generoMundo(), moldeMundo(), (mundoAtual() || {}).lexico).map((l) => ({ ...l, onde: "dentro" }));
  const fora = arredoresDaCidade(sementeMundo(), cid).map((a) => ({ ...a, onde: "arredores" }));
  const aqui = lugarRef.current;
  const anfitriao = aqui && dentro.find((l) => semNome(l.nome) === semNome(aqui.nome));
  const comodos = anfitriao
    ? comodosDoLocal(sementeMundo(), anfitriao, generoMundo(), moldeMundo()).map((q) => ({ ...q, onde: "comodo", dentroDe: anfitriao.nome }))
    : [];
  /* quem já está num cômodo pode voltar para o salão: o próprio anfitrião
     continua na lista, e é o que faz "desço para o salão" funcionar */
  const paiDoComodo = aqui && aqui.dentroDe ? dentro.find((l) => semNome(l.nome) === semNome(aqui.dentroDe)) : null;
  const irmaos = paiDoComodo
    ? comodosDoLocal(sementeMundo(), paiDoComodo, generoMundo(), moldeMundo()).map((q) => ({ ...q, onde: "comodo", dentroDe: paiDoComodo.nome }))
    : [];
  return [...comodos, ...irmaos, ...dentro, ...fora];
};

/* ---------------- O QUE A CENA USA (v9.54) ----------------
   As perguntas que decidem quais blocos de regra sobem no prompt deste
   turno. Todas são baratas e todas saem dos refs vivos — nenhuma
   adivinha nada, que é a régua da porta: se o sistema não sabe dizer se
   a situação está acontecendo, o bloco fica.

   Onde existe um `resumo*Prompt`, a pergunta é ele mesmo devolver vazio.
   Não é preguiça: essas funções JÁ carregam o teste de "não há nada a
   dizer sobre isto", e escrever o teste uma segunda vez aqui seria criar
   duas verdades que podem discordar. */
/* ---------------- O ESPAÇO DA MESA (v9.104) ----------------
   O retrato que o Geógrafo lê. Nenhum campo aqui é inventado: todos
   saem de refs que já existiam e que ninguém tinha juntado. É a mesma
   função que `situacaoDaMesa` faz para o Bibliotecário. */
const espacoDaMesa = () => {
  const mm = masmorraRef.current;
  const naMasmorra = !!(mm && !mm.encerrada);
  const lug = lugarRef.current;
  const cid = (mapaRef.current.cidades || []).find((c) => c.nome === cidadeAtualRef.current) || null;
  const dentro = !!(lug && lug.distancia === "dentro") || naMasmorra;
  /* de que TIPO é o prédio em que estou, quando estou num. O lugar
     guarda o nome; os locais da cidade guardam o tipo — e é o tipo que
     o acervo lê, porque é ele que diz o que o espaço comporta. */
  let tipoDoLocal = "";
  if (lug && lug.nome && cid) {
    const achado = locaisDaCidade(sementeMundo(), cid, generoMundo(), moldeMundo(), (mundoAtual() || {}).lexico)
      .find((l) => semNome(l.nome) === semNome(lug.nome));
    if (achado) tipoDoLocal = achado.tipo;
  }
  /* v9.104: e quando o lugar foi INVENTADO pela ficção — o caso comum,
     porque o Mestre nomeia lugares livremente —, o nome às vezes se
     entrega: "A Taverna do Corvo", "o Templo Pálido". `tiposPedidos` já
     sabe ler isso e existia para outra coisa.

     Quando o nome não denuncia nada ("O Escudo das Velas"), o tipo fica
     vazio e as afordâncias de lugar não disparam. É o lado seguro: um
     tipo chutado daria ao Narrador uma regra sobre um lugar que talvez
     não seja aquele. */
  if (!tipoDoLocal && lug && lug.nome) tipoDoLocal = tiposPedidos(lug.nome)[0] || "";
  const sit = situacaoDaMesa();
  const cl = climaRef.current;
  return garantirEspaco({
    tipo: naMasmorra ? "masmorra" : jornadaRef.current ? "estrada" : lug ? "lugar" : cidadeAtualRef.current ? "cidade" : "nenhum",
    rotulo: naMasmorra ? mm.nome : (lug && lug.nome) || cidadeAtualRef.current || "",
    tipoDoLocal,
    bioma: biomaDaqui(),
    porte: (cid && (cid.porte || cid.tipo)) || "",
    dentro,
    aberto: !dentro && !naMasmorra,
    apertado: naMasmorra,
    /* a sala do chefe e a cripta são fundo de saco: uma saída só */
    fundo: naMasmorra && saidasDe(mm).length <= 1,
    alto: naMasmorra,
    agua: /pantano|costa/.test(biomaDaqui()) && !dentro,
    saidas: naMasmorra ? Math.max(1, saidasDe(mm).length) : dentro ? 2 : 4,
    /* lá embaixo a luz é a tocha; aqui em cima é a hora */
    luz: naMasmorra ? (mm.tochas > 0 ? "penumbra" : "escuro") : (ehNoite(minutoRef.current) && !dentro ? "penumbra" : "clara"),
    publico: !!cidadeAtualRef.current && !acampadoRef.current && !naMasmorra,
    gentePorPerto: sit.gentePorPerto,
    cabem: naMasmorra ? 4 : dentro ? 10 : 20,
    emCombate: !!combateRef.current,
    emMasmorra: naMasmorra,
    emViagem: !!jornadaRef.current,
    acampado: !!acampadoRef.current,
    noite: ehNoite(minutoRef.current),
    clima: (cl && cl.rotulo) || "",
    montado: false,
  });
};

/* ---------------- A PAUTA DO TURNO (v9.104) ----------------
   Um lugar só, ordenado e com teto, para tudo o que o Mestre decidiu.
   Nasce com o Geógrafo dentro; cada sistema se muda para cá quando
   chegar a vez dele. */
/* ---------------- O QUE A OPOSIÇÃO QUER (v9.110) ----------------
   Traduz o combate para a situação que o acervo do Adversário sabe
   ler. As palavras do LUGAR vêm do Geógrafo prontas — duas versões do
   mesmo chão seria a garantia de que uma das duas ia mentir. */
/* Os alvos como o Adversário os enxerga. Serve só para a LINHA da
   Pauta poder nomear quem apanha — a escolha de verdade acontece
   dentro do `turnoDosInimigos`, com as bandeiras que só o motor sabe
   (alcance contra a grade, quem está no caminho). */
const alvosDaLuta = () => {
  try {
    const p0 = fichaViva() || personagem || {};
    const grupo = (p0.grupo || []).filter((g) => (g.vida || 0) > 0);
    return [
      { ref: "jogador", nome: p0.nome, vida: p0.vida, vidaMax: p0.vidaMax, nivel: p0.nivel, heroi: true,
        conjurador: perfilCombate(p0.classe || "").tipo === "conjurador" },
      ...grupo.map((g, i) => ({ ref: "grupo", nome: g.nome, vida: g.vida, vidaMax: g.vidaMax || g.vida, nivel: g.nivel || 1, i,
        conjurador: perfilCombate(g.classe || "").tipo === "conjurador",
        cura: ["Clérigo", "Druida", "Bardo"].includes(g.classe || "") })),
    ];
  } catch (e) { return calou("alvosDaLuta", e); }
};

const lutaDaMesa = () => {
  try {
    const c = combateRef.current;
    if (!c || !(c.inimigos || []).length) return null;
    const p0 = fichaViva() || personagem || {};
    const vivos = (c.inimigos || []).filter((e) => !e.derrotado && (e.vida || 0) > 0);
    if (!vivos.length) return null;
    const e = espacoDaMesa();
    const grupo = (p0.grupo || []).filter((g) => (g.vida || 0) > 0);
    const somaVida = vivos.reduce((s, x) => s + (x.vida || 0), 0);
    const somaMax = vivos.reduce((s, x) => s + (x.vidaMax || x.vida || 1), 0) || 1;
    /* quem fala pela oposição é o mais forte de pé: um bando tem uma
       intenção só, e é a de quem manda nele. */
    const voz = vivos.reduce((a, b) => ((b.nivel || 0) + PESO_AMEACA[b.ameaca] * 10 > (a.nivel || 0) + PESO_AMEACA[a.ameaca] * 10 ? b : a), vivos[0]);
    const mente = menteDaCriatura(voz.nome, voz.desc, (mundoAtual() || {}).lexico);
    const av = avaliarEncontro(vivos, p0);
    const mm = masmorraRef.current;
    return {
      nome: voz.nome, ameaca: voz.ameaca || "comum",
      ehBicho: mente === "besta", ehMorto: mente === "morto",
      ehTropa: vivos.length >= 4 && new Set(vivos.map((x) => x.nome)).size <= 2,
      ehChefe: !!voz.chefe || voz.ameaca === "lendario",
      pensa: mente !== "besta" && mente !== "morto",
      rodada: c.rodada || 1,
      quantos: vivos.length, quantosEram: (c.inimigos || []).length,
      minhaVida: (voz.vida || 0) / (voz.vidaMax || voz.vida || 1),
      vidaDosMeus: somaVida / somaMax,
      faixa: (av && av.faixa && av.faixa.id) || "",
      heroiVida: (p0.vida || 0) / (p0.vidaMax || 1),
      heroiCaido: (p0.vida || 0) <= 0,
      heroiSozinho: grupo.length === 0,
      quantosDoOutroLado: 1 + grupo.length,
      temConjurador: [p0, ...grupo].some((x) => perfilCombate(x.classe || "").tipo === "conjurador"),
      temCurandeiro: grupo.some((x) => ["Clérigo", "Druida", "Bardo"].includes(x.classe || "")),
      alguemFerido: [p0, ...grupo].some((x) => (x.vida || 0) > 0 && (x.vida || 0) < (x.vidaMax || 1) * 0.5),
      heroiFamoso: famaAtual() >= 45,
      heroiCarrega: (mm && !mm.encerrada && mm.temChave) ? "a chave da masmorra" : "",
      apertado: e.apertado, aberto: e.aberto, fundo: e.fundo, alto: e.alto,
      agua: e.agua, escuro: e.luz === "escuro", saidas: e.saidas,
      publico: e.publico, emMasmorra: e.emMasmorra,
      ondeCai: e.alto ? (e.emMasmorra ? "o poço da sala" : "a beira") : "",
      euEmbosquei: !!c.emboscada && !c.surpresaDoJogador,
      fuiEmboscado: !!c.emboscada && !!c.surpresaDoJogador,
      temRefem: !!c.refem, temCivil: e.gentePorPerto > 0 && !e.emMasmorra,
      protejoAlgo: (mm && !mm.encerrada && voz.chefe) ? "o que está atrás dele" : "",
      protegidoQuebrou: false,
      querSaber: "",
      temLider: vivos.length > 1, liderCaiu: (c.inimigos || []).some((x) => x.chefe && (x.derrotado || (x.vida || 0) <= 0)),
      doVilao: !!(nemesisRef.current && nemesisRef.current.nome) && !!c.doVilao,
      ordemDoVilao: (c.doVilao && (nemesisRef.current || {}).arquetipo) ? "o que a ameaça mandou" : "",
      /* o vies da postura: o adversario fica receoso no apice, aproveitador na crise */
      posturaMoral: moralDoInimigo((posturaRef.current || {}).postura),
    };
  } catch (e) { calou("lutaDaMesa", e); return null; }
};

/* A intenção da luta e o que ela virou. A memória é por COMBATE: sem
   ela não existe "virou", existe só "agora é outra" — e um inimigo que
   troca de plano toda rodada não tem plano. */
const intencaoDaLuta = () => {
  const s = lutaDaMesa();
  if (!s) return null;
  const v = intencaoDaVez(s, { antes: intencaoRef.current || "" });
  if (!v || !v.intencao) return null;
  return { ...v, situacao: s };
};

/* O QUE O MUNDO FAZ SOBRE UMA COISA DE TRÊS DIAS ATRÁS (v9.112).
   Ele lê o REGISTRO, que já é o livro-razão: o quê, quando, onde,
   quem viu, o peso e agora o ato. Nada de estrutura nova. */
const oQueOMundoCobra = () => {
  try {
    return consultarCobrador(registroRef.current, {
      dia: diaRef.current,
      cobradas: cobradasRef.current,
      fama: Math.round(famaAtual()),
      ultimaCobranca: ultimaCobrancaRef.current,
      ultimasFormas: formasCobradasRef.current,
      publico: !!(espacoDaMesa() || {}).publico,
      temGente: pessoasDaCena().length > 0,
    });
  } catch (e) { calou("oQueOMundoCobra", e); return null; }
};

/* Achar a cidade no mapa era feito em três lugares, cada um com a sua
   própria comparação de caixa e de acento. Um lugar só. */
const cidadeDoMapa = (nome) => ((mapaRef.current && mapaRef.current.cidades) || [])
  .find((c) => String(c.nome || "").toLowerCase() === String(nome || "").toLowerCase()) || null;

/* MM14: as tres fichas da mesa (cidade, gente, mercado) para uma frase —
   extraido de `pautaDoTurno` para que o sinal do oraculo
   (`ehPerguntaAoMundo`) tambem possa perguntar as fichas antes de rolar
   o d100. Quando `presentes` nao vem pronto (o sinal so tem a frase),
   calcula-se aqui pelo mesmo elenco da cena que `pautaDoTurno` usa. */
/* E1: o porte da terra em número (o `pouso.fator` da ficha da cidade) —
   a caneca e o quarto falam da mesma terra. 1 quando não há cidade. */
const fatorDoPouso = () => {
  try {
    const cd = cidadeDoMapa(cidadeAtualRef.current);
    if (!cd) return 1;
    const f = fichaDaCidade(cd, { semente: sementeMundo(), mapa: mapaRef.current, lex: (mundoAtual() || {}).lexico, genero: generoMundo(), molde: moldeMundo() });
    const n = Number(f && f.pouso && f.pouso.fator);
    return Number.isFinite(n) && n > 0 ? n : 1;
  } catch (e) { calou("fatorDoPouso", e); return 1; }
};

const fichasDaMesa = (frase = "", presentes = null) => {
  if (!Array.isArray(presentes)) {
    try {
      presentes = elencoDaCena(npcsRef.current, cidadeAtualRef.current, mapaRef.current, { comGrupo: (personagemRef.current || personagem || {}).grupo || [], masmorra: masmorraRef.current }).aqui;
    } catch (e) { calou("elencoDaCena em fichasDaMesa", e); presentes = []; }
  }
  /* MM14: os nomes que a mesa ja conhece — a gente em cena e o lugar onde
     se esta —, para as fichas apagarem o nome proprio antes de procurar o
     assunto ("o Sino Calado" nao pergunta pelo sino). Uma vez so, e as
     tres fichas (a cidade, a gente, o mercado) a usam. */
  const nomesDaMesa = [...Object.keys(npcsRef.current || {}), (lugarRef.current && lugarRef.current.nome) || ""].filter(Boolean);
  let fc = null;
  try {
    if (cidadeAtualRef.current && !jornadaRef.current && !masmorraRef.current && !combateRef.current) {
      let foraDeHora = [];
      try { foraDeHora = sinosForaDeHora(aberturaMundoRef.current, { dia: diaRef.current, cidade: cidadeAtualRef.current }); } catch (e) { calou("sinosForaDeHora", e); }
      fc = fichaParaPauta(cidadeDoMapa(cidadeAtualRef.current), {
        semente: sementeMundo(), mapa: mapaRef.current, lex: (mundoAtual() || {}).lexico,
        genero: generoMundo(), molde: moldeMundo(), dia: diaRef.current, minuto: minutoRef.current, frase,
        nomes: nomesDaMesa, foraDeHora,
        /* E1: "dentro dos muros" com número — do ponto do herói, não do centro */
        aqui: meuPonto(),
      });
    }
  } catch (e) { calou("fichaParaPauta", e); }
  /* MM8a: a gente por dentro — so quando a frase pergunta por alguem */
  let gp = null;
  try {
    if (!combateRef.current) {
      let recentes = [];
      try { recentes = (mensagensRef.current || []).filter((m) => m && (m.autor === "jogador" || m.autor === "mestre")).slice(-4).map((m) => m.texto); } catch (e) { calou("recentes da gente por dentro", e); }
      gp = genteParaPauta({
        semente: sementeMundo(), mapa: mapaRef.current, cidade: cidadeAtualRef.current,
        genero: generoMundo(), molde: moldeMundo(), lex: (mundoAtual() || {}).lexico,
        base: baseMundoRef.current, npcs: npcsRef.current, presentes, espinha: espinhaRef.current, guildas: guildasRef.current, estado: elencoSaveRef.current,
        grupo: (personagemRef.current || personagem || {}).grupo || [],
        heroi: (personagemRef.current || personagem || {}).nome || "",
        recentes, lugar: lugarRef.current, dia: diaRef.current, minuto: minutoRef.current, frase,
        nomes: nomesDaMesa,
      });
    }
  } catch (e) { calou("genteParaPauta", e); }
  /* MM14: o preco perguntado — a mesma frase, a banca de hoje. Nunca em
     luta (ali nao ha banca) nem fora de cidade (nao ha onde comprar). */
  let mc = null;
  try {
    /* 9.ª sessão (v9.433): também na estrada, quando há carroça — e com a
       moeda do mundo, para o preço dizer a unidade */
    const bancas = bancasDaCena();
    mc = (!combateRef.current && bancas.length) ? mercadoParaPauta(bancas, frase, { onde: jornadaRef.current ? "" : (cidadeAtualRef.current || ""), moeda: moedaDoMundo() }) : null;
  } catch (e) { calou("mercadoParaPauta", e); }
  /* 11/10 (MM11 · 5.ª sessão, J9): o preço do BALCÃO de mantimentos — as
     rações, as tochas, a corda do kit. A banca não os vende, e a pauta
     ia vazia: o Mestre inventou "dez cunhas, mais uma pela corda boa".
     Entra na mesma ficha do mercado (é ela que cala o oráculo). */
  try {
    if (!combateRef.current && cidadeAtualRef.current) {
      const p0 = personagemRef.current || personagem || {};
      const bc = balcaoParaPauta(frase, { balcao: balcaoAqui(cidadeDoMapa(cidadeAtualRef.current)), temKit: garantirSuprimentos(p0.suprimentos).kit, moeda: moedaDoMundo() });
      if (bc.pergunta.length) mc = { pergunta: [...((mc && mc.pergunta) || []), ...bc.pergunta], em: [...((mc && mc.em) || []), ...bc.em] };
    }
  } catch (e) { calou("balcaoParaPauta", e); }
  /* MM17 C2: as terras de além da região — só quando a frase pergunta por
     elas, nunca na masmorra nem na luta. É ficha do mundo: o oráculo não
     rola o que o mapa sabe (`A_FICHA_DECIDE`). */
  let hz = null;
  try {
    hz = horizonteDaPergunta(frase, mapaRef.current, { masmorra: masmorraRef.current, luta: !!combateRef.current });
  } catch (e) { calou("horizonteDaPergunta", e); }
  /* E1 (o Narrador só narra): o preço COMUM perguntado (a caneca, o prato
     quente, o pão) — a tabela pelo porte da terra. A banca não os vende e
     a pauta ia vazia: o Mestre inventava o número. */
  let pc = null;
  try {
    pc = (!combateRef.current && cidadeAtualRef.current) ? precoComumParaPauta(frase, { fator: fatorDoPouso(), moeda: moedaDoMundo() }) : null;
  } catch (e) { calou("precoComumParaPauta", e); }
  return { cidade: fc, gente: gp, mercado: mc, horizonte: hz, preco: pc };
};

/* ---------------- F2a · EM CENA: o que existe à volta do herói ----------------
   O contexto de `montarEmCena` (em-cena.js), um só para a pauta e para a
   leitura do golpe: o grupo e quem anda comigo, o registo daqui, o núcleo
   em cena, o que o Mestre mostrou, a criatura da estrada (só no mesmo
   trecho), a luta, a sala, a banca à vista (o critério de bancasDaCena),
   a moeda do mundo, a frase e o lugar. Cada fonte num calou: uma que
   estoura deixa a lista mais curta, nunca o turno sem ela. */
const quemAndaComigo = (grupo) => {
  const doGrupo = new Set((grupo || []).map((g) => String((g && g.nome) || "").toLowerCase()));
  return Object.values(npcsRef.current || {})
    .filter((n) => n && n.nome && String(n.relacao || "").toLowerCase() === "companheiro" && String(n.status || "vivo").toLowerCase() === "vivo" && !doGrupo.has(String(n.nome).toLowerCase()))
    .map((n) => n.nome);
};

const contextoDoEmCena = (frase, aqui) => {
  const p0 = personagemRef.current || personagem || {};
  const vale = (rotulo, f, seNao) => { try { return f(); } catch (e) { calou(rotulo, e); return seNao; } };
  const nucleo = vale("EM CENA · o núcleo", () => nucleoAgora(), null);
  const mm = masmorraRef.current;
  return {
    semente: sementeMundo(),
    turno: turnoDeRegistroRef.current + 1,
    cidade: cidadeAtualRef.current || "",
    presentes: aqui || [],
    grupo: p0.grupo || [],
    comigo: vale("EM CENA · quem anda comigo", () => quemAndaComigo(p0.grupo), []),
    emCena: nucleo ? vale("EM CENA · o núcleo em cena", () => nucleoEmCena(nucleo), []) : [],
    nucleo,
    mostrado: vale("EM CENA · o que o Mestre mostrou", () => falasDoMestre(mensagensRef.current), []),
    encontro: vale("EM CENA · a criatura da estrada", () => { const v = criaturaAVistaRef.current, j = jornadaRef.current; return (v && j && v.trecho === (j.de || "") + ">" + (j.para || "")) ? v : null; }, null),
    combate: combateRef.current,
    sala: vale("EM CENA · a sala", () => (mm && !mm.encerrada && Array.isArray(mm.salas)) ? (mm.salas.find((x) => x.id === mm.atual) || null) : null, null),
    /* 10.ª sessão (v9.455, EM_CENA_DO_LUGAR): quem o sistema sabe longe não
       entra na lista do que está à frente, por mais que a prosa o nomeie —
       a MESMA conta da linha LONGE da pauta */
    longe: vale("EM CENA · quem está longe", () => elencoDaCena(npcsRef.current, cidadeAtualRef.current, mapaRef.current, { comGrupo: p0.grupo || [], masmorra: mm }).longe || [], []),
    bancas: vale("EM CENA · as bancas", () => bancasDaCena(), []),
    moeda: moedaDoMundo(),
    frase: String(frase || ""),
    lugar: lugarRef.current,
    antes: emCenaRef.current,
    /* 13/10 (v9.461): a espinha diz quem a historia pos noutra cidade
       (longeDaHistoria), e os sitios daqui saem do texto antes de se
       procurar bicho nele (BICHO_DO_SITIO: a Serpente Rouca e uma casa) */
    espinha: espinhaRef.current,
    lugares: vale("EM CENA · os sítios", () => lugaresDaqui().map((l) => l.nome), []),
  };
};

const pautaDoTurno = (acaoDoTurno = "") => {
  let p = garantirPauta(null);
  cobrouAgoraRef.current = false;
  /* quem está longe já é calculado pelo elenco da cena — o Geógrafo lê
     dali em vez de refazer a conta, porque duas versões da mesma
     verdade é como nasce o balanceamento fantasma desta casa */
  const { longe, aqui } = elencoDaCena(npcsRef.current, cidadeAtualRef.current, mapaRef.current, { comGrupo: (personagemRef.current || personagem || {}).grupo || [], masmorra: masmorraRef.current });
  const g = paraPauta({
    ...contextoDoEspaco(),
    espaco: espacoDaMesa(),
    lex: (mundoAtual() || {}).lexico,
    sitio: acampadoRef.current ? sitioRef.current : null,
    clima: (climaRef.current && climaRef.current.rotulo) || "",
    longe,
  });
  p = porNaPauta(p, "onde", g.onde);
  /* MM16 nº 4: A PLANTA À VOLTA DA SALA (a sala mesma vai na 1.ª linha do
     ONDE, que é de ferro). Fora da masmorra a função devolve nada. Na
     luta, uma linha só: quem está e a quantos metros é do tabuleiro. */
  try {
    p = porNaPauta(p, "masmorra", masmorraParaPauta(masmorraRef.current, { luta: !!combateRef.current }));
  } catch (e) { calou("masmorraParaPauta", e); }
  /* MM17 C2: e, numa campanha com região, o que se sabe DE FORA do lugar
     (a ficha: o tipo, o perigo, quem anda por lá, as horas até à base).
     Na luta não entra: lá a secção é a linha do tabuleiro. */
  try {
    p = porNaPauta(p, "masmorra", linhaDaFicha(mapaRef.current, masmorraRef.current, { luta: !!combateRef.current }));
  } catch (e) { calou("linhaDaFicha", e); }
  /* 06/10: A LUZ DA LUTA — o escuro, a minha tocha, quem enxerga no
     escuro. Vazia com tudo claro; prio barata (pauta.js). */
  try {
    if (combateRef.current) p = porNaPauta(p, "luz", luzParaPauta(luzDaLutaAgora(), { heroi: combateRef.current.heroi, inimigos: combateRef.current.inimigos || [] }));
  } catch (e) { calou("luzParaPauta", e); }
  /* MM (a luta tem saída): A VISTA DA LUTA. Na quinta sessão a prosa disse
     "o dragão sumiu" com ele a 1,5 m, pôs Hakon a gritar a 0/12 e trocou a
     cabeçada pelo sopro — o Narrador lia os golpes do meio da rodada e
     nunca o estado do fim dela. Três linhas, dentro do teto da pauta: quem
     está de pé e no chão, os vetos de quem caiu e de quem não sumiu, e os
     golpes que o sistema nomeou. */
  try {
    const cV = combateRef.current;
    if (cV) {
      const gR = golpesDaRodadaRef.current;
      const vista = vistaDaLuta({ heroi: fichaViva(), inimigos: cV.inimigos || [], lugar: cV.heroi || null,
        golpes: gR && gR.rodada === (cV.rodada || 1) - 1 ? gR.golpes : [] });
      p = porNaPauta(p, "quem", vista.quem);
      p = porNaPauta(p, "vetoDoDesfecho", vista.vetos);
      p = porNaPauta(p, "naoPode", vista.naoPode);
    }
  } catch (e) { calou("a vista da luta na pauta", e); }
  /* v9.138: o que este lugar produz e o que lhe falta. Vai em ONDE porque
     é geografia antes de ser economia — a praça de um porto e a de uma
     serra não se parecem, e o Narrador nunca teve como saber disso.
     MM16 nº 5: a seção é "economia" (rótulo ONDE, prio 2,5). Como 4.ª
     linha do ONDE ela tinha prio 1,3 e, numa masmorra, os 264 caracteres
     de Vau Fincado tiravam do teto a frase do golpe final (sessão 3, M21
     e M30). Na cidade lê-se igual; na luta cede (`cederNaCena`, abaixo). */
  p = porNaPauta(p, "economia", envelopeDoComercio(cidadeDoMapa(cidadeAtualRef.current), diaRef.current));
  /* v9.139: e, se este chão for seu, o que você decidiu sobre ele. Só
     quando o herói está lá — governo de longe não é o que se vê na praça. */
  {
    const cd = cidadeDoMapa(cidadeAtualRef.current);
    if (cd && cd.relacao === "jogador" && !masmorraRef.current) { /* MM16 nº 4: o domínio é a praça, não a masmorra */
      p = porNaPauta(p, "onde", envelopeDoDominio(cd, (governosRef.current || {})[cd.nome], {
        felicidade: ((reinoRef.current || {})[cd.nome] || {}).felicidade,
        semente: sementeMundo(),
      }));
    }
  }
  /* v9.129: A SECAO `momento` estava declarada em `pauta.js` desde a v9.104
     e nunca era preenchida — uma porta sem leitor. A espinha e o leitor
     dela: "a batida da historia" e exatamente o marco em que se esta. */
  /* v9.133: pertencer a uma casa muda como o mundo trata o heroi, e isso e
     cena. Vai em ONDE porque e do mesmo naipe do lugar: contexto que
     colore tudo o que acontece dentro dele. */
  {
    const casa = minhaCasa();
    if (casa && !masmorraRef.current) p = porNaPauta(p, "onde", envelopeDaGuilda(casa)); /* MM16 nº 4: lá dentro a casa não é o lugar */
  }
  p = porNaPauta(p, "momento", envelopeDaEspinha(espinhaRef.current, historiaRef.current.etapa, estruturaPorId(historiaRef.current.estrutura)));
  /* v9.391: a marca do antagonista no momento, o JÁ SE SABE do segredo que
     acabou de cair, o que o mundo lembra de quem chegou a tempo */
  let maoDoVilao = false; /* MM-C C2: a marca ou os servos do fio nesta cena (o vilão do núcleo só pede pela mão) */
  try { const mf = momentoDoFio(espinhaRef.current, historiaRef.current.etapa, { dia: diaRef.current, vilao: nemesisRef.current }); p = porNaPauta(p, "momento", mf); const assin = String(((espinhaRef.current || {}).fio || {}).assinatura || ""); if (assin && (mf || []).some((l) => String(l).includes(assin))) maoDoVilao = true; } catch (e) { calou("o momento do fio", e); }
  /* o episodio em curso fala pelo mesmo canal do arco: e a batida de
     dentro da batida — o cerco que a Jornada esta vivendo agora. */
  if (episodioRef.current && episodioRef.current.aberto) p = porNaPauta(p, "momento", envelopeDoEpisodio(episodioRef.current));
  /* a Noite-torneio fala pelo mesmo canal: a chave, o rival, o teto do
     interludio — instrucao de mesa, nunca nome de sistema */
  if (modoRef.current === "rapida" && noiteRef.current && noiteRef.current.prato === "torneio" && torneioRef.current && !combateRef.current) {
    p = porNaPauta(p, "momento", envelopeDaChave(torneioRef.current) + " " + provocacaoDoRival(torneioRef.current) + " " + oEnvelopeDoFio("interludioDoTorneio"));
  }
  /* MM13: o prenúncio do sino é um aviso de UM turno — a pauta o consome
     e apaga, para não repeti-lo enquanto ele espera para encher de vez. */
  if (sinoDoTurnoRef.current) { p = porNaPauta(p, "momento", sinoDoTurnoRef.current); sinoDoTurnoRef.current = ""; }
  /* v9.118: a vizinhança tem seção própria e prioridade baixa — numa cena
     cheia a gente presente ganha dela, e é isso que se quer */
  p = porNaPauta(p, "daqui", g.daqui);
  /* MM12: a cidade por dentro — o hoje e a língua sempre, a resposta ao
     que o jogador perguntou só quando ele pergunta. Nunca em jornada, em
     masmorra nem em combate: ali não há rua para se perguntar nada dela. */
  /* MM14: as tres fichas da mesa (cidade, gente, mercado), pela mesma
     frase e o mesmo elenco desta cena — agora em fichasDaMesa, para que
     o sinal do oraculo tambem consiga perguntar. */
  const { cidade: fc, gente: gp, mercado: mc, horizonte: hz, preco: pc } = fichasDaMesa(acaoDoTurno, aqui);
  if (fc) p = porNaPauta(p, "cidade", fc.cidade);
  /* MM14: as três fichas juntam-se numa mesa só, pela ordem em que a
     frase pediu cada coisa — não pela ordem em que os módulos correram. */
  p = porNaPauta(p, "pergunta", juntarRespostas([fc, gp, mc, hz, pc]));
  /* E1 (o Narrador só narra): O PREÇO da rua — a cena mostra preços sem
     ninguém perguntar, e é melhor que os mostre certos. Só com rua. */
  try {
    if (cidadeAtualRef.current && !jornadaRef.current && !masmorraRef.current && !combateRef.current) p = porNaPauta(p, "preco", precosDaRua(fatorDoPouso(), { moeda: moedaDoMundo() }));
  } catch (e) { calou("precosDaRua", e); }
  /* E1: NOMES À MÃO — dois nomes livres da cultura, para o figurante que a
     cena pede. Ninguém do registo, do elenco nem do grupo. Ficam pendentes:
     só contam como oferecidos se a linha chegar ao texto. */
  nomesPendentesRef.current = null;
  try {
    const p0 = personagemRef.current || personagem || {};
    const usados = [...Object.values(npcsRef.current || {}), ...nomesDoElenco(), ...(p0.grupo || []), p0.nome || ""].filter(Boolean);
    const nomes = nomesAMao({ semente: sementeMundo(), dia: diaRef.current, cidade: cidadeAtualRef.current || "", genero: generoMundo(), lex: (mundoAtual() || {}).lexico, usados });
    const linha = linhaDosNomesAMao(nomes);
    if (linha) { p = porNaPauta(p, "nomes", linha); nomesPendentesRef.current = { nomes, linha }; }
  } catch (e) { calou("nomesAMao", e); nomesPendentesRef.current = null; }
  p = porNaPauta(p, "naoPode", g.naoPode);
  /* 11/10 (MM11 · 5.ª sessão, M10): a compra ou a dádiva que a frase
     declarou e o sistema não fechou — o Narrador não entrega o que a
     bolsa não pagou */
  /* MM-C · C0: se o próprio turno abriu o combate (a agressão declarada), o
     veto da luta sem painel já não é verdade e não viaja */
  try { if (combateRef.current && (naoPodeDoTurnoRef.current || []).includes(LUTA_SEM_PAINEL.veto)) naoPodeDoTurnoRef.current = naoPodeDoTurnoRef.current.filter((v) => v !== LUTA_SEM_PAINEL.veto); } catch (e) { calou("o veto da luta com o combate aberto", e); }
  try { p = porNaPauta(p, "naoPode", naoPodeDoTurnoRef.current || []); } catch (e) { calou("o veto da bolsa da frase", e); }
  /* MM13: enquanto o mural espera, o veto vai junto do do geógrafo. */
  p = porNaPauta(p, "naoPode", vetosDaAbertura({ abertura: aberturaMundoRef.current, missoes: missoesRef.current }));
  /* MM15 (4): o segredo que a espinha guarda não é a boca do Narrador —
     o veto só nasce quando a frase do turno nomeia um segredo de pé. */
  try {
    p = porNaPauta(p, "naoPode", vetoDoSegredo(acaoDoTurno, segredosGuardados(espinhaRef.current, mundoDaBase()), { lugar: (lugarRef.current && lugarRef.current.nome) || "" }));
  } catch (e) { calou("vetoDoSegredo", e); }
  /* O JUIZ CORRIGE: a invenção da resposta anterior que o sistema contradiz,
     com o número certo — só no turno logo a seguir, ou quando a frase toca a
     coisa (vetosParaAPauta). O turno é o do textoDaPauta. */
  try { p = porNaPauta(p, "vetoDoJuiz", ...vetosParaAPauta(vetosDoJuizRef.current, { turno: turnoDeRegistroRef.current + 1, cidade: cidadeAtualRef.current || "", frase: acaoDoTurno })); } catch (e) { calou("o veto do juiz na pauta", e); }
  /* v9.165: A LEI DA FORMA na cena — quem guarda este andar, o estado da
     maré do porto. Só parado em cidade: no meio da estrada a linha do
     andar de trás seria mentira sobre o lugar onde a cena está. */
  if (!jornadaRef.current && !masmorraRef.current) { /* MM16 nº 4: a lei do andar é a da cidade, não a da masmorra */
    const lf = leiParaPauta({
      molde: moldeMundo(), semente: sementeMundo(), mapa: mapaRef.current,
      forma: formaRef.current, lex: (mundoAtual() || {}).lexico, genero: generoMundo(),
      cidadeAtual: cidadeAtualRef.current, dia: diaRef.current,
    });
    p = porNaPauta(p, "onde", lf.onde);
    p = porNaPauta(p, "naoPode", lf.naoPode);
  }
  /* v9.105: O ARQUIVISTA. Ele não resume a campanha — recupera as três
     linhas que importam a ESTA cena, com esta gente, neste lugar. O
     custo é fixo para sempre: uma campanha de mil turnos entrega as
     mesmas três que uma de trinta. */
  /* v9.106: O INTÉRPRETE. Uma linha por pessoa presente, no máximo
     três. Ele diz o que cada uma FAZ; o que ela DIZ continua sendo do
     Narrador, e é onde ele é insubstituível. */
  {
    /* v9.135: o Interprete e consultado UMA vez por turno, em `enviar`,
       porque o ATOR precisa do movimento antes de a Pauta ser montada.
       Consultar duas vezes sortearia dois movimentos e marcaria memoria
       duas vezes — a pessoa faria uma coisa e falaria sobre outra. */
    const r = interpreteRef.current || interpreteParaPauta(pessoasDaCena(), { elenco: elencoMemRef.current });
    p = porNaPauta(p, "gente", r.linhas);
    if (!interpreteRef.current) for (const m of r.marcas) elencoMemRef.current = marcarMovimento(elencoMemRef.current, m.nome, m.id, m.gesto);
    p = porNaPauta(p, "fala", envelopeDasFalas(falasDoTurnoRef.current));
    /* v9.137: a seção ACABOU ("o que o sistema resolveu agora") estava
       declarada na Pauta e não tinha UM produtor sequer. É exatamente o
       lugar do propósito que amadureceu: o Mestre já resolveu, e o
       Narrador só narra o momento em que aparece. */
    p = porNaPauta(p, "acabou", (propositosDoTurnoRef.current || []).map((x) => x.envelope).join("\n"));
    /* MM10: o crime deste turno (testemunhas, a lei, o preço) — uma vez
       só, e depois limpo; e o veto de quem é procurado aqui, todo turno
       em que durar. */
    try {
      if (crimeDoTurnoRef.current) {
        p = porNaPauta(p, "acabou", crimeDoTurnoRef.current.acabou || []);
        p = porNaPauta(p, "naoPode", crimeDoTurnoRef.current.naoPode || []);
        crimeDoTurnoRef.current = null;
      }
      p = porNaPauta(p, "naoPode", procuradoParaPauta(leiRef.current, { cidade: cidadeAtualRef.current, dia: diaRef.current }).naoPode);
    } catch (e) { calou("crimeParaPauta", e); }
  }
  /* MM13: O MUNDO PINGA FIOS — no máximo uma linha por turno, da primeira
     pessoa em cena que tiver algo a dizer sobre a principal. */
  try {
    for (const pessoa of aqui || []) {
      const fio = fioParaAPrincipal({ abertura: aberturaMundoRef.current, missoes: missoesRef.current, semente: sementeMundo(), pessoa });
      if (fio) { p = porNaPauta(p, "gente", fio); break; }
    }
  } catch (e) { calou("o fio da abertura", e); }
  /* v9.108: O ALIADO AGE POR CONTA PRÓPRIA. Um por turno, e só um: o
     silêncio dos outros é o que faz a vez de cada um valer alguma
     coisa. */
  /* v9.110: O ADVERSÁRIO. Uma linha, e ela é a mesma coisa que a
     mecânica vai fazer: a prioridade de alvo desta intenção é a que
     entra no `turnoDosInimigos` logo abaixo. Uma intenção que não muda
     o alvo seria adjetivo. */
  {
    const v = intencaoDaLuta();
    if (v) {
      const antes = intencaoRef.current || "";
      intencaoRef.current = v.intencao.id;
      p = porNaPauta(p, "contra", linhaDaLuta(v.situacao, alvosDaLuta(), { antes }));
      /* a VIRADA é fato consumado e vai ao canon, não à Pauta: a Pauta
         diz o que vale agora, o canon diz o que já aconteceu e não se
         desfaz. Sai uma vez só, na rodada em que virou. */
      const env = envelopeDaVirada(v.situacao, { antes });
      if (env) notaRef.current = `${notaRef.current ? notaRef.current + "\n" : ""}${env}`;
    }
  }
  {
    const r = aliadoParaPauta(aliadosDaCena());
    if (r.linhas.length) {
      p = porNaPauta(p, "aliado", r.linhas);
      marcarQueFalou(r.quem);
      if (r.vaiEmbora) aliadoVaiEmbora(r.quem);
    }
  }
  /* v9.107: A AMEAÇA PENSA. Duas linhas no máximo — o que ela concluiu
     e o que faz por causa disso. A leitura sobe junto de propósito: sem
     ela a resposta parece arbitrária, e com ela o Narrador sabe se está
     encenando um vilão que acertou ou um que se enganou. */
  {
    const r = respostaDaAmeaca();
    if (r) maoDoVilao = true;
    /* nexo (11/10): o nome só depois do rosto — o mesmo motivo do arco */
    if (r) p = porNaPauta(p, "vilao", vilaoParaPauta(r, { nome: ((nemesisRef.current || {}).conhecido && (nemesisRef.current || {}).nome) || "a ameaça" }));
  }
  /* v9.112: O MUNDO LEMBROU. Raro de propósito — uma vez a cada cinco
     dias, no máximo. A dívida só é marcada como cobrada DEPOIS de a
     linha entrar na Pauta: marcar antes perderia a conta para sempre
     se ela não coubesse, e em silêncio. */
  {
    const r = oQueOMundoCobra();
    const linha = r ? linhaDoMundo(r) : "";
    if (linha) {
      p = porNaPauta(p, "mundo", linha);
      cobrouAgoraRef.current = true;
      cobradasRef.current = [...cobradasRef.current, r.chave].slice(-200);
      ultimaCobrancaRef.current = diaRef.current;
      formasCobradasRef.current = [...formasCobradasRef.current, r.cobranca.id].slice(-6);
      notaRef.current = `${notaRef.current ? notaRef.current + "\n" : ""}${envelopeDoMundo(r)}`;
    }
  }
  /* v9.142: quem são as potências, o que cada uma quer e o que acha de
     você. Vai em O MUNDO porque é o mundo em volta — e vai SEMPRE, não
     só quando o mundo cobra uma dívida antiga. */
  p = porNaPauta(p, "mundo", envelopeDasPotencias(potenciasAqui(), diplomaciaRef.current));
  try { p = porNaPauta(p, "antes", saidaParaPauta(sementeMundo(), mapaRef.current, contextoDoElenco(), elencoSaveRef.current, { dia: diaRef.current, cidade: cidadeAtualRef.current }).antes); } catch (e) { calou("saidaParaPauta", e); }
  /* MM-C C2: QUEM CARREGA — uma batida por turno, da subtrama de quem está
     em cena (subtramas.js). Como a QUEM É, só conta se chegar ao texto:
     fica pendente, e o envio confirma (confirmarCoracao). O que um clique
     decidiu (a decisão, o porquê) entra uma vez, no turno que ele envia. */
  let quemCarrega = "";
  try {
    const fala = coracaoFalaRef.current;
    coracaoFalaRef.current = null;
    if (fala && fala.linha) p = porNaPauta(p, fala.secao === "pergunta" ? "pergunta" : "coracao", fala.linha);
    const nucleo = nucleoAgora();
    const frase = String(acaoDoTurno || "").trimStart().startsWith("[") ? "" : String(acaoDoTurno || "");
    const ctx = contextoDoCoracao(nucleo, { frase, maoDoVilao });
    const r = fala && fala.proprio ? { coracao: coracaoRef.current, linha: "", quem: "", efeitos: [], longe: [], batida: null } : avancarCoracao(coracaoRef.current, nucleo, ctx); /* o turno que o próprio coração envia é a batida dele: nenhuma outra no mesmo fôlego */
    if (r.linha) p = porNaPauta(p, "coracao", r.linha);
    if ((r.longe || []).length) p = porNaPauta(p, "foraDeCena", r.longe.map((x) => x && x.texto).filter(Boolean));
    quemCarrega = r.quem || "";
    coracaoPendenteRef.current = { r, turno: ctx.turno, emCena: ctx.emCena };
  } catch (e) { calou("avancarCoracao", e); coracaoPendenteRef.current = null; }
  /* MM-C C1: QUEM É — a ficha por dentro de quem do núcleo está em cena,
     uma pessoa por turno, e a mesma só de tantos em tantos turnos
     (nucleo.js), no turno que a pauta leva. O ritmo só conta se a linha
     CHEGA ao texto (o teto pode cortá-la): fica pendente, e o envio confirma. */
  try {
    const nucleo = nucleoAgora();
    const esp = espinhaRef.current || {};
    const turnoQ = turnoDeRegistroRef.current + 1;
    const q = { ultimas: {}, cenas: {}, ...(quemERef.current || {}), pendente: null };
    const r = quemEParaPauta(nucleo, { emCena: nucleoEmCena(nucleo), ato: (historiaRef.current || {}).etapa || 0, ultimoAto: Math.max(0, (esp.atos || []).length - 1), turno: turnoQ, ultimas: q.ultimas, cenas: q.cenas, fio: esp.fio || null, jaCarrega: quemCarrega, ...elencoDoCoracao(), espinha: esp, cidade: cidadeDoCoracao() }); /* 13/10 (v9.461): quem a historia sabe longe nao leva a ficha */
    p = porNaPauta(p, "quemE", ...(r.quemE || []));
    quemERef.current = { ...q, pendente: r.quem && r.quemE && r.quemE[0] ? { quem: r.quem, turno: turnoQ, linha: r.quemE[0] } : null };
  } catch (e) { calou("quemEParaPauta", e); } try { p = porNaPauta(p, "foraDeCena", foraDeCenaParaPauta(elencoSaveRef.current, { dia: diaRef.current, cidade: cidadeAtualRef.current, npcs: npcsRef.current, emCena: (() => { try { const c = (mensagensRef.current || []).filter((m) => m && m.autor === "mestre").slice(-2).map((m) => m.texto).join(" "); return Object.keys(npcsRef.current || {}).filter((nm) => c.includes(nm)); } catch (e2) { return []; } })() }).foraDeCena); } catch (e) { calou("foraDeCenaParaPauta", e); }
  p = porNaPauta(p, "antes", arquivistaParaPauta(registroRef.current, {
    onde: linhaDoLugarDaMesa(),
    quem: (elencoDaOnda().aqui || []),
    assunto: (compassoRef.current || {}).assunto || "",
    turnoAtual: turnoDeRegistroRef.current,
    diaAtual: diaRef.current,
  }));
  /* ---------------- O PESO DA CENA (v9.204) ----------------
     Reconhece a gravidade dos fatos do turno, poe o peso na pauta e
     CALA o mundo pelo canal do veto (mercado, oferta e trabalho somem).
     Um peso por cena — pesoDaCena ja garante isso. Consome e limpa: o
     peso e um beat, e "solta" e o jogador seguir quando quiser. */
  try {
    const cena = pesoDaCena(fatosDoPesoRef.current);
    if (cena) ultimoPesoRef.current = { peso: cena.peso, dia: diaRef.current };
    if (cena) {
      p = porNaPauta(p, "peso", "Esta cena tem PESO: " + cena.nome + " — " + cena.diz + ". Quem tem laco com isto comparece.");
      p = porNaPauta(p, "naoPode", vetoDoPeso(cena.peso));
    }
    fatosDoPesoRef.current = {};
  } catch (e) { /* o peso nunca pode custar o turno */ }

  /* ---------------- A MESA POSTA (v9.201) ----------------
     Quando a acao declarada casa com uma situacao conhecida, as DUAS
     versoes da cena chegam ao Narrador ANTES do dado — e a de falha
     nomeia a moeda, a lei que impede o "nada acontece". Casa
     conservador (chave forte) e fica de fora do combate, que tem
     resolucao propria. Nunca custa o turno. */
  try {
    if (!combateRef.current) {
      const sit = situacaoQueCasa(acaoDoTurno);
      if (sit) { const ap = apostas(sit); if (ap) p = porNaPauta(p, "mesa", "Se " + ap.sePassa, "Se " + ap.seFalha, ap.noMeio ? "Se " + ap.noMeio : ""); }
    }
  } catch (e) { /* a aposta nunca pode custar o turno */ }
  /* ---------------- MM3: O GOLPE FINAL, NA PAUTA ----------------
     O envelope nasce em `continuarGolpeDoJogador` (aplicarEscolha ja
     resolvido) e mora num ref ate a PROXIMA montagem da pauta -- que e
     sempre a narracao do proprio golpe (`enviar` monta a pauta uma vez
     por turno). Consome e limpa: um golpe final e um fato de UM turno,
     nunca do proximo. */
  try {
    const gf = golpeFinalEnvelopeRef.current;
    if (gf) p = golpeFinalNaPauta(p, gf); /* MM14: o "como" era cortado pelo teto em ACABOU (prio 3,1) e nunca chegava; vai em DESFECHO */
  } catch (e) { /* o golpe final nunca pode custar o turno */ }
  golpeFinalEnvelopeRef.current = null;
  /* ---------------- MM6: O ESCONDIDO FORA DA LUTA ----------------
     Dentro da luta a linha e a do tabuleiro (resumoGridPrompt, em `enviar`);
     aqui e o veto — quem nao me viu nao pode reagir a mim por conta propria. */
  try {
    if (!combateRef.current) {
      const peEsc = pautaDoEscondido(personagemRef.current || personagem, { presentes: aqui });
      if (peEsc) p = porNaPauta(p, "naoPode", peEsc.naoPode);
    }
  } catch (e) { /* o veto do escondido nunca pode custar o turno */ }
  /* MM18: O RUMO — reagir e responder primeiro, depois UMA ponte para o
     próximo passo da principal; e, se o jogador está fora do fio há
     turnos, o degrau da escada (o sinal, quem vem buscar, a cobrança).
     Fora da luta: lá a ordem do turno é a do tabuleiro. Entra ANTES de
     `cederNaCena` porque nada vem depois dele, e não cede: "rumo" não
     está em nenhuma lista de `SECOES_QUE_CEDEM`. */
  try {
    if (!combateRef.current && modoRef.current !== "rapida") {
      const rumo = linhaDoRumo({
        pedido: lerOPedido(acaoDoTurno),
        degrau: degrauDaEscuta(garantirEscuta(escutaRef.current).semAvanco),
        passo: proximoPasso({ abertura: aberturaMundoRef.current, missoes: missoesRef.current }),
        semente: diaRef.current,
        /* MM19 (v9.394, o backend): o mundo que o degrau do encalhe precisa
           para virar cena com nome e lugar — onde estou, o fio aberto, a
           espinha e o ato, o dia, e quem anda contra mim */
        mundo: { aqui: (g.onde || [])[0] || "", abertura: aberturaMundoRef.current, missoes: missoesRef.current,
                 espinha: espinhaRef.current, ato: historiaRef.current.etapa, dia: diaRef.current, vilao: nemesisRef.current,
                 /* 12.ª sessão: quem o Mestre já nomeou está em cena, e não se apresenta de novo */
                 mostrado: falasDoMestre(mensagensRef.current) },
      });
      if (rumo) p = porNaPauta(p, "rumo", rumo);
    }
  } catch (e) { calou("o rumo na pauta", e); }
  /* A CAMPANHA QUE PRENDE (item 1): O QUE VOLTA — a promessa que a narração
     plantou e o sistema guardou volta quando amadurece. Anda o relógio, por
     isso UMA vez por turno (pautaDoTurno só é chamada em `enviar`). Fora da
     Noite: lá não há campanha para prometer. */
  try {
    if (modoRef.current !== "rapida") {
      const rv = cobrarNoTurno(prometidoRef.current, {
        pedido: lerOPedido(acaoDoTurno), luta: !!combateRef.current,
        fio: fioDaHistoria({ abertura: aberturaMundoRef.current, missoes: missoesRef.current }),
        mortos: (baseMundoRef.current || {}).mortos || [],
      });
      prometidoRef.current = rv.estado;
      if (rv.linha) p = porNaPauta(p, "volta", rv.linha);
    }
  } catch (e) { calou("o que volta na pauta", e); }
  /* (item 2): O FECHO — como acaba a resposta deste turno, nunca o anterior;
     no fim do ato, a escolha com preço (a batida que vira o ato). */
  try {
    let fimDeAto = false;
    try { fimDeAto = !!((marcoAtual(espinhaRef.current, historiaRef.current.etapa) || {}).batida || {}).fecho; } catch (e) { calou("o fim do ato", e); }
    const fx = escolherFecho({
      pedido: lerOPedido(acaoDoTurno), luta: !!combateRef.current, fimDeAto,
      gente: (pessoasDaCena() || []).length > 0 || ((personagemRef.current || {}).grupo || []).length > 0,
      ultimo: fechoRef.current,
      sorte: rng(hashSemente(sementeMundo() + "|fecho|" + turnoDeRegistroRef.current)),
    });
    fechoRef.current = fx.id;
    p = porNaPauta(p, "fecho", fx.linha);
  } catch (e) { calou("o fecho na pauta", e); }
  /* MM16 nº 5: O QUE CEDE ONDE. A tabela é do motor (`SECOES_QUE_CEDEM`);
     aqui só se diz que cena é esta. `arredores` é FORA DOS MUROS — sem
     cidade (estrada, jornada) ou num lugar marcado `distancia: "arredores"`
     —, o mesmo sinal de `ondeSeProcura`; `lugarRef` sozinho não serve,
     porque também guarda o lugar "dentro" (a taberna, a praça). */
  try {
    const fora = !cidadeAtualRef.current || !!(lugarRef.current && lugarRef.current.distancia === "arredores");
    p = cederNaCena(p, { luta: !!combateRef.current, masmorra: !!masmorraRef.current, arredores: fora });
  } catch (e) { calou("cederNaCena", e); }
  /* F2a · EM CENA: o sistema entrega ao Mestre a lista do que existe, e a
     linha engole os NOMES À MÃO (que continuam a ser confirmados pela linha
     deles, que vai dentro). Depois do cederNaCena: na luta não entra (a
     vista da luta já é a lista), e a linha encolhe até não tirar nada. */
  try {
    const lista = montarEmCena(contextoDoEmCena(acaoDoTurno, aqui));
    emCenaRef.current = lista;
    p = pautaComEmCena(p, lista, { luta: !!combateRef.current, turno: turnoDeRegistroRef.current + 1 });
  } catch (e) { calou("EM CENA", e); }
  return p;
};

/* ---------------- QUEM ANDA COMIGO (v9.108) ----------------
   Traduz o grupo para a situação que o acervo do aliado sabe ler. A
   alma de cada um nasce na primeira vez que ele é visto e nunca muda:
   uma pessoa que troca de código toda semana não tem código. */
const aliadosDaCena = () => {
  try {
    const p0 = fichaViva() || personagem || {};
    const grupo = p0.grupo || [];
    if (!grupo.length) return [];
    const mem = garantirAliados(aliadosRef.current);
    const pares = paresEntre(npcsRef.current);
    const ctxAto = contextoDoAto();
    return grupo.map((g) => {
      const nome = g.nome || "";
      if (!mem[nome]) mem[nome] = nascerAliado(nome);
      const a = mem[nome];
      if (a.saiu) return null;
      const v = vontadePorId(a.vontade);
      const atrito = pares.find((x) => x.tipo === "rivalidade" && (x.a === nome || x.b === nome)
        && grupo.some((o) => (o.nome || "") === (x.a === nome ? x.b : x.a)));
      return {
        nome,
        vontade: a.vontade,
        vontadeTexto: (v && v.o) || "",
        apodrecerTexto: (v && v.apodrece) || "",
        etapa: a.etapa,
        apodrecendo: a.parada >= DIAS_ATE_APODRECER * 0.6,
        apodreceu: a.apodreceu,
        codigoTexto: (codigoPorId(a.codigos[0]) || {}).o || "",
        cruzouAgora: !!cruzouOCodigo(a, contextoDoAto()),
        cruzou: a.cruzou,
        vinculo: Number(g.vinculo) || 50,
        calado: a.calado,
        atritoCom: atrito ? (atrito.a === nome ? atrito.b : atrito.a) : "",
        publico: !!cidadeAtualRef.current && !acampadoRef.current,
        emCidade: !!cidadeAtualRef.current,
        acampado: !!acampadoRef.current,
        emCombate: !!combateRef.current,
        ato: atoDoTurnoRef.current,
        /* o contexto do ato entra JUNTO da cena: as opiniões leem os
           dois e separá-los foi o que fez a primeira versão calar */
        ...ctxAto,
      };
    }).filter(Boolean);
  } catch (e) { return calou("aliadosDaCena", e); }
};

/* O contexto que o CÓDIGO consulta. Grosseiro de propósito: um código
   cruzado por engano custa uma cena; um nunca cruzado custa o módulo
   inteiro, porque a peça que faz a relação gastar deixa de existir. */
const contextoDoAto = () => {
  const p0 = fichaViva() || personagem || {};
  return {
    ato: atoDoTurnoRef.current,
    presente: (p0.grupo || []).length > 0,
    emCombate: !!combateRef.current,
    rendido: false,
    suborno: atoDoTurnoRef.current === "paguei" && /suborn|calar|compr[oa]/i.test(String(ultimaAcaoRef.current || "")),
    alguemPrecisava: atoDoTurnoRef.current === "ignorei" && (contRef.current.pedidosRecusados || 0) > 0,
    quebreiPromessa: false, roubeiPobre: false, fugi: (contRef.current.fugas || 0) > 0,
    escolhiEstranho: false, usoProibido: false, saqueiCorpo: false, quebreiLei: false,
    poupei: (contRef.current.poupados || 0) > 0,
  };
};

/* Depois de falar, ele cala por um tempo. E quem NÃO falou fica mais
   perto da vez dele — é o que faz o grupo se revezar sozinho. */
const marcarQueFalou = (quem) => {
  const mem = garantirAliados(aliadosRef.current);
  for (const [nome, a] of Object.entries(mem)) {
    mem[nome] = { ...a, calado: nome === quem ? 0 : a.calado + 1 };
  }
  aliadosRef.current = mem;
};

const aliadoVaiEmbora = (quem) => {
  const mem = garantirAliados(aliadosRef.current);
  if (!mem[quem]) return;
  mem[quem] = { ...mem[quem], saiu: true };
  aliadosRef.current = mem;
  mudarFicha((p) => ({ ...p, grupo: (p.grupo || []).filter((g) => (g.nome || "") !== quem) }));
  pushMsgs([{ autor: "sistema", texto: `${quem} pegou as coisas dele e foi embora.` }]);
  notaRef.current = (notaRef.current ? notaRef.current + "\n" : "") + oEnvelopeDaGente("companheiroFoiEmbora", { quem });
};

/* ---------------- A MENTE DA AMEAÇA (v9.107) ----------------
   O retrato que o Sistema Vilão lê. Nenhum campo é inventado: o plano
   vem de `vilao.js`, o que chegou até ele vem do livro-razão, e o
   herói pelos olhos dele sai da ficha e dos contadores. */
const menteDaAmeaca = () => {
  const v = nemesisRef.current;
  if (!v || !v.nome) return null;
  const p0 = fichaViva() || personagem || {};
  const saber = garantirSaber(saberRef.current);
  const naoSabe = oQueEleNaoSabe(saber, (registroRef.current || []).filter((x) => x.peso >= 2));
  return {
    nome: v.nome, arquetipo: v.arquetipo, corpo: v.corpo || "pessoa",
    passo: v.passo || 0, conhecido: !!v.conhecido, marcas: (v.marcas || []).length,
    quanto: saber.length,
    certezaMax: saber.reduce((a, x) => Math.max(a, certezaDe(x)), 0),
    ignora: naoSabe.length,
    fama: Math.round(famaAtual()),
    nivel: p0.nivel || 1,
    heroiFerido: (p0.vida || 0) < (p0.vidaMax || 1) * 0.5,
    heroiSozinho: !(p0.grupo || []).length,
    heroiRico: (p0.moedas || 0) >= 300,
    heroiMatou: (contRef.current.inimigosDerrotados || 0) > 0,
    heroiPoupou: (contRef.current.poupados || 0) > 0,
    heroiFugiu: (contRef.current.fugas || 0) > 0,
    heroiAceitouAlgo: (contRef.current.contratos || 0) > 0,
    perto: !!(v.marcas || []).some((m) => String(m).includes(cidadeAtualRef.current || "\u0000")),
    dia: diaRef.current,
    desdeQueAgiu: diaRef.current - vilaoAgiuRef.current,
  };
};

const respostaDaAmeaca = () => {
  try {
    const m = menteDaAmeaca();
    if (!m) return null;
    const r = responder(m);
    if (r) vilaoAgiuRef.current = diaRef.current;
    return r;
  } catch { return null; }
};

const pessoasDaCena = () => {
  try {
    const p0 = fichaViva() || personagem || {};
    const { aqui } = elencoDaCena(npcsRef.current, cidadeAtualRef.current, mapaRef.current, { comGrupo: p0.grupo || [], masmorra: masmorraRef.current });
    const quantos = aqui.length;
    const daBase = oQueExisteAqui(sementeMundo(), mapaRef.current, cidadeAtualRef.current, baseMundoRef.current, generoMundo(), moldeMundo(), (mundoAtual() || {}).lexico);
    const confid = confidenciasRef.current || [];
    return aqui.map((x) => {
      const nome = typeof x === "string" ? x : x.nome;
      const n = npcsRef.current[nome] || {};
      const l = garantirLaco(n.laco);
      const daBaseEla = ((daBase && daBase.gente) || []).find((g) => g.nome === nome) || {};
      const noGrupo = (p0.grupo || []).some((g) => (g.nome || "") === nome);
      return {
        nome,
        papel: n.papel || daBaseEla.papel || "",
        temperamento: n.traco || daBaseEla.traco || "",
        quer: daBaseEla.vontade || n.notas || "",
        teme: n.segredo || "",
        relacao: n.relacao || "desconhecido",
        laco: (l && l.tipo) || "",
        forcaDoLaco: (l && !l.rompido && l.forca) || 0,
        rompido: !!(l && l.rompido),
        euDevo: /d[íi]vida|devo|prometi/i.test(String(n.notas || "")) || (l && l.tipo === "divida"),
        /* 11/10 (MM11 · 5.ª sessão, M35): quem recebeu de mim sem que eu
           pedisse nada fica a dever (`registarABolsaDaFrase`) — o sinal
           que o Intérprete e a índole já liam e ninguém acendia */
        meDeve: !!n.meDeve,
        sabeDeMim: confid.some((c) => (c.ouvintes || []).includes(nome)),
        euSeiDela: !!n.segredo,
        primeiraVez: n.conhecidoEm == null && !noGrupo, /* v9.315: dia 0 é conhecido, não "nunca vi" (!n.conhecidoEm tratava os dois igual) */
        viuAntes: (() => { try { return jaMeViuAntes(n, { hoje: diaRef.current, vistos: (elencoSaveRef.current || {}).vistos }); } catch (e) { calou("viuAntes", e); return false; } })(),
        ato: atoDoTurnoRef.current,
        quantosEscutam: Math.max(0, quantos - 1),
        aSos: quantos <= 1,
        emPerigo: !!combateRef.current || (personagemRef.current || personagem || {}).vida < ((personagemRef.current || personagem || {}).vidaMax || 1) * 0.35,
        emCombate: !!combateRef.current,
        noLugarDela: !!(lugarRef.current && daBaseEla.local && lugarRef.current.nome === daBaseEla.local),
        tocaramNoSegredo: !!n.segredo && /segredo|verdade|passado|de onde|quem [ée]/i.test(atoDoTurnoRef.current === "pedi" ? "pergunta" : ""),
        ehCompanheiro: noGrupo,
        fama: Math.round(famaAtual()),
        noite: ehNoite(minutoRef.current),
      };
    });
  } catch (e) { return calou("pessoasDaCena", e); }
};

/* O rótulo curto do lugar, que o registro guarda e o Arquivista casa.
   Curto de propósito: "no Escudo das Velas" casa com "no Escudo das
   Velas, dentro de Forte do Vigia" na comparação por prefixo. */
const linhaDoLugarDaMesa = () => {
  const mm = masmorraRef.current;
  if (mm && !mm.encerrada) return mm.nome;
  if (lugarRef.current && lugarRef.current.nome) return lugarRef.current.nome;
  if (jornadaRef.current) return `estrada para ${jornadaRef.current.para || "adiante"}`;
  return cidadeAtualRef.current || "";
};

/* Onde eu estou, em coordenada. É esta a posição que a tela desenha, que
   o Mestre recebe e que a boca de uma masmorra guarda ao ser aberta. */
const meuPonto = () => { try { return (posicaoDoHeroi(contextoDoEspaco()) || {}).coord || null; } catch (e) { calou("meuPonto", e); return null; } };

/* ONDA 3 DO CUSTO (14/10): a relevância do turno (relevancia.js: o que o turno cita pelo nome, quem a cena tem, onde o herói está), lida pela gente, pelo cânone, pelas masmorras e pelos esconderijos; se a pauta trouxe a linha A GENTE (a porta do bloco que a ensina); e os nomes da gente da cidade (a GENTE POR CONHECER não os repete). Montados em enviar, junto dos sinais; fora de um turno ou se estourarem, null — e tudo vai como antes. Não vão ao save. */
 /* o herói tem o que governar: facção, cidade sua, governo, cidade a ser
    tomada, ou uma casa de que é membro (a guilda do painel de Gestão) */
 const temOQueGovernar = () => {
   try {
     return !!faccaoJogadorRef.current
       || ((mapaRef.current || {}).cidades || []).some((c) => c && c.relacao === "jogador")
       || Object.keys(governosRef.current || {}).length > 0
       || !!tomandoRef.current
       || (guildasRef.current || []).some((g) => g && g.membro);
   } catch (e) { calou("o herói tem o que governar", e); return true; }
 };

const cenaDoPrompt = () => {
  const p = fichaViva() || personagem || {};
  const sinais = sinaisDoTurnoRef.current || SINAIS_ABERTOS;
  const mm = masmorraRef.current;
  const cena = {
    emCombate: !!combateRef.current,
    emMasmorra: !!(mm && !mm.encerrada),
    /* v9.115: há um chamado em curso? É a porta da raid. */
    emRaid: !!(raidRef.current && raidRef.current.fase === "luta"),
    /* v9.117: há uma missão DO SISTEMA aberta? É a porta da trama. */
    temTrama: (missoesRef.current || []).some((m) => m && m.status === "ativa" && m.tipo === "trama"),
    /* v9.120: a porta da mesa de dois abre quando há de fato duas
       cadeiras ocupadas — não quando há uma sala aberta e vazia. */
    emSala: ocupadosDaSala(salaRef.current).length >= LUGARES,
    /* v9.106: há alguém em cena? É a porta do Intérprete. */
    temGente: pessoasDaCena().length > 0,
    temVilao: !!(nemesisRef.current && nemesisRef.current.nome),
    /* v9.112: a Pauta deste turno traz uma cobrança do mundo? */
    temCobranca: !!cobrouAgoraRef.current,
    temChao: (chaoRef.current || []).length > 0,
    emCidade: !!cidadeAtualRef.current,
    /* dentro de um PRÉDIO da cidade — não nos arredores. A régua é a
       distância, que já sabe distinguir uma escada de uma caminhada. */
    dentroDeUmLocal: !!(lugarRef.current && lugarRef.current.distancia === "dentro" && cidadeAtualRef.current),
    /* cidade tem mercador; ermo não tem. É a mesma pergunta, e é honesta:
       a regra de compra e venda importa onde há de quem comprar. */
    /* ONDA 2 DO CUSTO: e a tabela de preços só abre quando o turno fala de
       comércio — na cidade ela abria em 96% dos turnos e é de onde vinham
       os preços inventados; o preço de verdade chega por PERGUNTOU e O PREÇO */
    temMercado: !!cidadeAtualRef.current && !!sinais.comercio,
    temGoverno: temOQueGovernar() || !!sinais.governo,
    fimDoAcampamento: !!sinais.fimDoAcampamento,
    temBancada: ((p.inventario || []).some((it) => !!comoComponente(it))),
    temMissao: !!resumoMissoesPrompt(missoesRef.current),
    conjura: perfilCombate(p.classe).tipo === "conjurador" || temCaderno(p)
      || (p.habilidades || []).some((h) => ehMagiaDoGrimorio(h && h.nome)),
    temGrupo: ((p.grupo || []).length > 0),
    temLegado: !!resumoLegadoPrompt(p),
    temSintonia: !!resumoSintoniaPrompt(p),
    temEspecializacao: !!p.especializacao,
    despertou: !!(divindadeRef.current && divindadeRef.current.despertar),
    invoca: (p.habilidades || []).some((h) => !!invocacaoDe(h)) || invocacoesDe(p).length > 0,
    /* o bloco explica como narrar um efeito que ACABA por acontecimento —
       sem efeito assim ativo, não há o que narrar */
    temGatilho: (p.efeitos || []).some((e) => gatilhosDe(e).length > 0),
    temDadiva: ((p.dadivas || []).length > 0) || (p.nivel || 1) >= 20,
    temRegraPropria: temRegraPropria(p),
    emViagem: !!jornadaRef.current, acampado: !!acampadoRef.current, genteNaPauta: genteNaPautaRef.current, /* onda 3 do custo: `acampado` nunca vinha, e a porta do acampamento (ACAMPAMENTO_PROMPT) nunca abria — o defeito que a onda 2 achou; `genteNaPauta` abre o bloco da GENTE EM CENA só com a linha A GENTE na pauta (null fora de um turno = a porta de antes) */
  };
  /* MM17 C2: lá dentro fecham o mercado, a cidade, a estrada e o prédio
     (PORTAS_NA_MASMORRA): 2.768 car. de regras de compra e venda por
     turno numa cripta. Fora dela, a mesma cena (o mesmo objeto). */
  try { return cenaNaMasmorra(cena); } catch (e) { calou("cenaNaMasmorra", e); return cena; }
};

/* ---------------- ONDE O ERMO ESTÁ (v9.54) ----------------
   A célula do trecho atual. Em viagem, o ponto do caminho já percorrido;
   parado fora de cidade, a célula de onde o herói ficou. Dentro da
   cidade não há ermo, e o prompt não recebe nada. */
const celulaAqui = () => {
  const semA = (s) => String(s || "").toLowerCase().normalize("NFD").replace(/[̀-ͯ]/g, "");
  const j = jornadaRef.current;
  if (j && j.para) {
    const rota = (mapaRef.current.rotas || []).find((r) =>
      (semA(r.de) === semA(j.de) && semA(r.para) === semA(j.para)) ||
      (semA(r.de) === semA(j.para) && semA(r.para) === semA(j.de)));
    const dias = Math.max(0.5, rota ? Number(rota.dias) || 3 : 3);
    const andados = Math.max(0, diaRef.current - (Number(j.desde) || diaRef.current));
    return celulaDaJornada(sementeMundo(), j, mapaRef.current, moldeMundo(), andados / dias);
  }
  if (cidadeAtualRef.current && !lugarRef.current) return null;
  const cid = (mapaRef.current.cidades || []).find((c) => semA(c.nome) === semA(cidadeAtualRef.current));
  return cid ? celulaDaCidade(sementeMundo(), cid, { mapa: mapaRef.current, molde: moldeMundo() }) : null;
};

/* v9.56: a linha da viagem passou a dizer PARA ONDE e QUANTO FALTA. Ela
   dizia só de onde e desde quando — o Mestre não sabia sequer o destino,
   e por isso escrevia "a estrada segue" turno após turno sem nunca
   apertar o ritmo. */
/* ---------------- O BIOMA DE ONDE EU ESTOU (v9.99) ----------------
   Esta busca estava copiada em quatro lugares, e as quatro cópias
   tinham o mesmo furo: fora de cidade devolviam "planicie". Quem
   forrageia no meio de um pântano colhia flor de planície, e o
   acampamento da estrada nascia sempre no mesmo descampado.

   Em viagem o bioma é o da cidade DE ONDE parti — a estrada atravessa
   a paisagem das duas pontas, e a de partida é a única que o sistema
   tem certeza de já ter visto. */
const biomaDaqui = () => {
  const cs = (mapaRef.current && mapaRef.current.cidades) || [];
  const acha = (nome) => (cs.find((c) => c.nome === nome) || {}).bioma || "";
  const j = jornadaRef.current;
  return acha(cidadeAtualRef.current) || (j ? acha(j.de) || acha(j.para) : "") || "planicie";
};

/* o nível é o da ficha VIVA (o ref, 4.ª fatia): o `personagem` do render
   é nulo nas closures que nascem no primeiro render (o aplicarResposta é
   uma delas), e a fama caía no nível 1 — o defeito 4 de 28/10 */
const famaAtual = () => calcularFama(contRef.current, ((personagemRef.current || personagem || {}).nivel) || 1, dominiosDe(mapaRef.current).length);

const tempoInfoPrompt = () => {
  const est = estacaoDe(diaRef.current);
  return `TEMPO DA CAMPANHA: hoje é ${dataTxt(diaRef.current)} — dia ${diaRef.current} da campanha —, ${horaTxt(minutoRef.current)}${ehNoite(minutoRef.current) ? " (NOITE)" : ""}, ${est.nome.toLowerCase()} ${est.icone} (${est.nota}). O app controla o relógio e o calendário: NUNCA estime datas ou horas por conta própria; use estas.`;
};

/* 11/10 (MM, o laço da história 4/6, v9.401 do backend): um vilão só — a
   lista de chefes obedece ao antagonista do fio. Se a leitura com a espinha
   estourar, a lista de antes volta: o prompt nunca fica sem chefes. */
/* ONDA 2 DO CUSTO: sem chefe em jogo no turno, só o antagonista e o +N */
const chefesDoFio = (soOAntagonista = false) => {
  try { return resumoChefesPrompt(sementeMundo(), mapaRef.current, baseMundoRef.current, generoMundo(), (mundoAtual() || {}).lexico, { espinha: espinhaRef.current, soOAntagonista }); }
  catch (e) { calou("os chefes do fio", e); return resumoChefesPrompt(sementeMundo(), mapaRef.current, baseMundoRef.current, generoMundo(), (mundoAtual() || {}).lexico); }
};

/* MM15 (4): o mundo que o segredo guardado precisa para saber o que um
   lugar É na base e quem lá trabalha — o mesmo formato de mundoDasTarefas. */
const mundoDaBase = () => ({ semente: sementeMundo(), mapa: mapaRef.current, genero: generoMundo(), molde: moldeMundo(), lex: (mundoAtual() || {}).lexico, base: baseMundoRef.current });

/* A TABELA DE FÉ (v7.5) mudou-se para o motor (T1-B, 27/10):
   motor/cronista.js#TABELA_DA_FE, com a população lida do mapa por
   `feDaTabela`. O juízo do Cronista entrega a conta feita. */

/* TÍTULO ÚNICO (v7.6): resolve o nome que a ficha mostra e que o Mestre usa.
   Fé tem precedência (é o que o herói É); sem fé, vale a fama. */
/* VÍNCULOS (v7.8): o Mestre não sabia se um companheiro te adora ou te
   tolera — então a intimidade das falas era chute. Agora ele sabe. */
const infoVinculos = () => {
  const g = ((personagem || personagemRef.current || {}).grupo || []).filter((x) => x && x.nome);
  if (!g.length) return "";
  const linhas = g.map((c) => {
    const v = typeof c.vinculo === "number" ? c.vinculo : VINCULO_INICIAL;
    return linhaDoVinculo(c.nome, v);
  });
  return `VÍNCULOS DO GRUPO (trate cada um com a intimidade certa — quem tem vínculo baixo NÃO faz confidências nem se sacrifica; quem tem vínculo alto puxa assunto pessoal, discorda com liberdade e arrisca a pele por mim): ${linhas.join("; ")}.`;
};

const infoRegras = () => {
  const p = personagem || personagemRef.current || {};
  const nv = p.nivel || 1;
  const prof = bonusProficiencia(nv);
  const chave = ATRIBUTOS.find((a) => ehProficiente(p.classe, a.id));
  /* ONDA 2 DO CUSTO: o ESTADO ÉPICO conta o XP de cada turno no nível 20 —
     saiu daqui (que vai ao texto fixo, em cache) para `infoEpico`, que vai
     ao ESTADO com o título */
  return `REGRAS DE PROGRESSÃO (o sistema calcula — não recalibre): proficiência +${prof} (nível ${nv}), somada automaticamente ao atributo que a classe domina${chave ? ` (${chave.nome})` : ""}. Um herói experiente rola alto no que é a especialidade dele — isso é esperado, não infle dificuldades para compensar. ESCALAS DE TEMPO (5e): uma rodada de combate dura 6 segundos; um turno de exploração de masmorra, 10 minutos; viagens contam em horas. Nunca descreva o tempo de forma incompatível com isso.`;
};

const infoEpico = () => {
  const ep = resumoEpico(personagem || personagemRef.current || {});
  return ep ? ` ESTADO ÉPICO: ${ep} — no ápice mortal o herói não sobe mais de nível; acumula XP e recebe dádivas épicas concedidas pelo sistema.` : "";
};

/* ONDA 2 DO CUSTO (13/10): o que o rodapé mandava a cada turno e só muda
   por campanha ou por nível — a forma do mundo, o treino das perícias, o
   que a profissão abre — sobe para o texto fixo, junto da ficha (o `fixo`
   de infoTitulo). Medido em 201 pedidos das 8.ª a 10.ª sessões: ~1,2 mil
   caracteres que não mudaram uma vez de um turno para o seguinte. Os
   PASSIVOS (somam bênção e equipamento), o traço (diz o que já foi gasto)
   e o deslocamento ficam no rodapé: mudam com o turno. */
const fixoDaFicha = () => {
  const p = personagemRef.current || personagem || {};
  const partes = [];
  try { partes.push(resumoMoldePrompt(moldeMundo())); } catch (e) { calou("a forma do mundo no fixo", e); }
  try { partes.push(resumoPericiasPrompt(p, (id) => atributoEfetivo(p, id), "treino")); } catch (e) { calou("as perícias no fixo", e); }
  try { partes.push(resumoProfissaoPrompt(p)); } catch (e) { calou("a profissão no fixo", e); }
  return partes.filter(Boolean).join("\n");
};

const infoTitulo = () => {
  /* usa o espelho: no carregamento do save o estado ainda não chegou */
  const p = personagem || personagemRef.current || {};
  const t = tituloDoHeroi(divindadeRef.current, patamarFama(famaAtual()).rotulo, patamarDe(p.nivel || 1).nome);
  const base = t.divino
    ? `${t.titulo} (GD ${t.gd} — título DIVINO, conquistado por fé, não por nível)`
    : `${t.titulo} (mortal — reconhecimento do mundo; NÃO é título divino)`;
  const acao = resumoAcaoDeTurno(p.classe, p.nivel || 1);
  const vinc = infoVinculos();
  const bocas = 1 + (p.grupo || []).length;
  const ermos = resumoErmos(p.suprimentos, p.exaustao, p.ritmoViagem, bocas);
  const bonus = acoesBonusDe(p.classe, p.nivel || 1);
  /* ONDA 2 DO CUSTO: o título, os suprimentos e os vínculos mudam com o
     jogo e vão ao ESTADO (`vivo`); a economia de ação, a ação de turno e a
     progressão só mudam com o nível e vão ao texto fixo (`fixo`), em cache */
  const regras = `${ECONOMIA_ACAO_PROMPT}${bonus.length ? ` AÇÕES BÔNUS DESTA CLASSE: ${bonus.map((b) => `${b.nome} (${b.desc})`).join("; ")}.` : " Esta classe não tem ação bônus própria — usa só a ação principal."} AÇÃO DE TURNO EM COMBATE: ${acao.texto} (${perfilCombate(p.classe).nota}). ${infoRegras()}`;
  let fixo = regras;
  try { const f = fixoDaFicha(); if (f) fixo = `${regras}\n${f}`; } catch (e) { calou("o fixo da ficha", e); }
  let epico = "";
  try { epico = infoEpico(); } catch (e) { calou("o estado épico", e); }
  return { vivo: `${base}. ${ermos}${epico}${vinc ? ` ${vinc}` : ""}`, fixo };
};

/* ---------------- O ARCO CASADO COM O MOTOR (v9.28) ----------------
   O arco corria por opinião do Mestre ("historia_avancar") e o motor corria
   por fato. Os dois descolavam: o jogador ficava em "O Abismo", com o Mestre
   instruído a narrar a derrota mais escura da campanha, enquanto o motor
   mostrava um mundo onde nada tinha acontecido ainda. O Mestre inventava o
   abismo do nada, e a história saía sem saber que rumo tomar.

   Agora o arco anda por MARCO, e marco é fato do motor: missão concluída,
   relógio que encheu, evento global encerrado, nêmesis abatida. As mesmas
   coisas que o jogador já viveu. */

/* O retrato do motor que o arco enxerga. Só refs — é chamado de dentro de
   callbacks antigos, e ler estado aqui traria o valor do primeiro render. */
/* `sobre.eventos` (T1-A 3.ª fatia): o bloco das missões, no motor,
   encerra o evento global ANTES de o marco virar o arco — e o ref ainda
   não o sabe; o motor passa o de agora */
const motorDoArco = (sobre = {}) => {
  const n = nemesisRef.current;
  const g = ((sobre && "eventos" in sobre ? sobre.eventos : eventosRef.current) || {}).global;
  const ms = missoesAtivas(missoesRef.current);
  return { marcosPendentes: (() => { try { const pa = progressoDoAto(espinhaRef.current, (historiaRef.current || {}).etapa || 0); return Math.max(0, pa.total - pa.feitos); } catch (e) { return undefined; } })(),
    /* nexo (11/10): o nome da nêmesis só sobe DEPOIS do rosto. Esta linha
       vai ao prompt em todo turno, e levava o nome desde o dia em que ela
       nascia — e a nêmesis agora é o antagonista da espinha (`vilaoDoFio`),
       cujo nome o fio guarda para o último ato. Antes do rosto ela já está
       na mesa como SOMBRA (`resumoVilaoPrompt`), sem nome. */
    nemesis: n && n.status !== "derrotada" && n.nome && n.conhecido ? n.nome : null,
    global: g && g.nome ? g.nome : null,
    /* nexo (11/10, contradição 7): a história principal abre as peças do
       arco, e o evento global corre ao lado dela (`resumoHistoria`). Sai
       de `impostas` para não ir duas vezes à mesma linha. */
    principal: (() => { try { return (ms.find((m) => m.tipo === "principal") || {}).titulo; } catch (e) { calou("a principal do arco", e); return undefined; } })(),
    impostas: ms.filter((m) => tipoMissao(m.tipo).forcada && m.tipo !== "principal").map((m) => `"${m.titulo}"`).slice(0, 3),
    relogios: (relogiosRef.current || []).map((r) => `${r.nome} ${barraDe(r)}`).slice(0, 3),
  };
};

/* o RITMO sobe junto do arco: uma linha, e ela não diz o movimento nem
   o assunto — diz só a tensão, que é o que a IA precisa para escolher o
   tamanho da própria voz. Saber que se está na véspera é saber que o
   clímax vem no turno seguinte, e isso apaga a única coisa que a véspera
   existe para dar. */
const resumoDoRitmo = () => { try { return resumoCompasso(compassoRef.current); } catch { return ""; } };

/* v9.91: o RITMO vai junto do arco, e num lugar so. `resumoDoArco` e
   passado a montarSystemPrompt em seis chamadas diferentes; acrescentar
   um parametro seria seis lugares para esquecer dele na setima. */
const resumoDoArco = () => [resumoHistoria(historiaRef.current, motorDoArco()), resumoDoRitmo()].filter(Boolean).join("\n");

/* ---------------- O BAÚ SÓ ONDE SE PROCURA (30/09, MM13b) ----------------
   `achavelAqui` precisa saber ONDE o herói está para não devolver o
   segredo de outro prédio ou o baú de outra estrada — ver mundo-base.js. */
const ondeSeProcura = () => {
  const l = lugarRef.current;
  return { lugar: (l && l.nome) || "", dentroDe: (l && l.dentroDe) || "", foraDosMuros: !cidadeAtualRef.current || !!(l && l.distancia === "arredores") };
};

/* ---------------- AS MAOS DA CASA (v9.133) ----------------
   Nenhuma regra mora aqui: tudo o que decide esta em `guildas.js`, e este
   bloco so aciona, guarda e conta ao jogador. */
const minhaCasa = () => (guildasRef.current || []).find((g) => g.membro) || null;

/* ---------------- A CONSULTA AO BIBLIOTECARIO (v9.85) ----------------
   O mestre ja escolhia bem QUAL fio puxar. O que ele nunca teve foi a
   segunda metade da decisao, que e a FORMA: um relogio quase cheio pode
   entrar numa cena de vinte maneiras, e o envelope pedia sempre a mesma
   — "traga isto a cena em duas ou tres frases". Pedido igual todo turno
   recebe resposta igual todo turno, e era dai que vinha a repeticao do
   narrador, nao da temperatura.

   Aqui o mestre monta a situacao com o que ele JA SABE — a mesa, o arco,
   a fase do vilao, quem esta na cena — e a estante devolve uma forma. O
   nome dela nao viaja: sobe a forma, nunca a etiqueta. */
/* ---------------- O QUE O MESTRE SABE DO LUGAR (v9.93) ----------------
   Tudo já existia: o mapa guarda porte, bioma e rotas com dias; o
   registro de gente sabe quem está aqui e quem está longe. O que não
   existia era alguém PERGUNTANDO antes de decidir — e por isso um cerco
   podia germinar numa aldeia sem portão, e um reencontro podia ser
   escolhido com a única pessoa conhecida sentada na minha frente. */
const lugarDaMesa = () => {
  try {
    const mapa = mapaRef.current || {};
    const cidades = mapa.cidades || [];
    const aqui = cidades.find((c) => c.nome === cidadeAtualRef.current) || null;
    const p0 = fichaViva() || {};
    const el = elencoDaCena(npcsRef.current, cidadeAtualRef.current, mapaRef.current, { comGrupo: p0.grupo || [] });
    /* a vizinha conhecida mais perto, em dias de estrada. Só conta o que
       o jogador JÁ descobriu: um caminho que ele não conhece não é uma
       saída, é névoa. */
    const conhecidas = new Set(cidades.filter((c) => c.descoberta).map((c) => c.nome));
    const dias = (mapa.rotas || [])
      .filter((r) => (r.de === cidadeAtualRef.current && conhecidas.has(r.para)) || (r.para === cidadeAtualRef.current && conhecidas.has(r.de)))
      .map((r) => Number(r.dias) || 0).filter((d) => d > 0);
    return {
      porte: (aqui && aqui.porte) || "",
      bioma: (aqui && aqui.bioma) || "",
      gentePorPerto: (el.aqui || []).length,
      genteLonge: (el.longe || []).length,
      diasAteVizinha: dias.length ? Math.min(...dias) : 0,
    };
  } catch { return {}; }
};

/* ---------------- O ELENCO QUE A ONDA CONSULTA (v9.97) ----------------
   "Os fins não sabem de quem falam: o sistema escolhe 'um amor que
   termina' sem saber se há um casal registrado nesta campanha."

   Agora sabe. `aqui` é quem está na cena e pode ser nomeado numa
   semente; `lacos` é quem já é alguma coisa de mim, por tipo. Um "amor
   que termina" só abre se houver um amor — e o nome dela sai daqui, não
   da imaginação de quem narra. */
const elencoDaOnda = () => {
  try {
    const p0 = fichaViva() || {};
    const el = elencoDaCena(npcsRef.current, cidadeAtualRef.current, mapaRef.current, { comGrupo: p0.grupo || [] });
    const lacos = { rompidos: comLaco(npcsRef.current, { rompido: true }) };
    for (const t of TIPOS_DE_LACO) lacos[t.id] = comLaco(npcsRef.current, { tipo: t.id, rompido: false });
    /* e os PARES que já existem entre gente do registro: é o que permite
       "os dois querem que eu escolha" saber quais dois, e é o que faz o
       mundo ter história sem mim no meio */
    return { aqui: (el.aqui || []).map((x) => x.nome).filter(Boolean), lacos, entre: paresEntre(npcsRef.current) };
  } catch { return { aqui: [], lacos: {} }; }
};

const situacaoDaMesa = ({ fio = "" } = {}) => {
  const p0 = fichaViva() || {};
  const h = historiaRef.current || {};
  const est = estruturaPorId(h.estrutura);
  const nEt = Math.max(1, (est.etapas || []).length - 1);
  const v = nemesisRef.current;
  const vivo = v && v.status !== "derrotada";
  const daqui = elencoDaCena(npcsRef.current, cidadeAtualRef.current, mapaRef.current, { comGrupo: p0.grupo || [] }).aqui || [];
  /* ---------------- O HISTORICO E DO SISTEMA (v9.86) ----------------
     Tres formas dependem de haver passado nesta campanha, e ate aqui quem
     decidia se havia era a IA: o `evite` mandava escolher outra forma se
     nao houvesse. Delegar essa pergunta e exatamente o que esta casa nao
     faz — o registro de pessoas e os feitos do arco estao do lado de ca.
     Uma IA que recebe "traga alguem que voce ja conhece" numa campanha de
     dois dias faz a unica coisa que pode: inventa a pessoa. */
  const feitos = (h.feitos || []).length;
  return {
    ordemDaFase: vivo ? (faseDe(v.fase).ordem) : -1,
    vilaoConhecido: !!(vivo && v.conhecido),
    momento: (Number(h.etapa) || 0) / nEt,
    temperatura: temperaturaDaMesa(mesaRef.current).id,
    pilarFaminto: (pilarFaminto(mesaRef.current) || {}).id || null,
    /* v9.88: e o oposto dele — o que o JOGADOR vem repetindo, para a
       estante parar de somar mais do mesmo em cima do que ele já traz */
    pilarRecente: (pilarRepetido(mesaRef.current) || {}).id || null,
    fio,
    pessoaNaCena: daqui.length > 0,
    emCidade: !!cidadeAtualRef.current,
    emMasmorra: !!masmorraRef.current,
    emCombate: !!combateRef.current,
    emViagem: !!jornadaRef.current,
    noite: ehNoite(minutoRef.current),
    temGrupo: (p0.grupo || []).length > 0,
    temPromessa: (missoesAtivas(missoesRef.current) || []).length > 0,
    temCicatriz: ((p0.cicatrizes || []).length > 0),
    temDerrotado: derrotadosDaSessaoRef.current.length > 0,
    temLugarAbandonado: (((mapaRef.current || {}).cidades) || []).some((c) => c.descoberta && c.nome !== cidadeAtualRef.current),
    temRelogio: (relogiosRef.current || []).some((x) => x.cheios > 0),
    temGenteConhecida: Object.keys(npcsRef.current || {}).length > 0,
    temPassado: feitos >= 2 || derrotadosDaSessaoRef.current.length > 0 || (p0.cicatrizes || []).length > 0,
    /* v9.87: tres memorias diferentes, e nao uma so. Um heroi com tres
       cicatrizes e nenhum quilometro rodado tem passado de sobra e nenhum
       lugar de que se lembrar; um que conversou duas vezes nao tem frase
       para ecoar. Os limiares sao baixos de proposito — a trava existe
       para a campanha RECEM-NASCIDA, nao para racionar a forma. */
    /* v9.88: contar NARRACOES era proxy grosso — doze paragrafos de
       travessia e descricao nao deixam uma frase para ecoar. Conta-se
       agora a narracao que tem FALA dentro (aspas ou travessao), que e o
       que o eco precisa que exista. Continua sendo proxy: se ha uma
       frase memoravel so a IA sabe, e este e o unico caso em que
       devolver a pergunta a ela seria defensavel. */
    temFalaAnterior: (mensagensRef.current || []).filter((m) => m && m.autor === "mestre" && /[“"”]|—s/.test(String(m.texto || ""))).length >= 8,
    temObjetos: (p0.inventario || []).length >= 3,
    temLugarVisitado: cidadesPisadas(mapaRef.current).length >= 2,
    ...lugarDaMesa(),
    pvBaixo: (p0.vida || 0) > 0 && (p0.vida || 0) <= Math.ceil((p0.vidaMax || 1) / 3),
    nivel: p0.nivel || 1,
    fama: famaAtual(),
  };
};

/* O cão de guarda da nêmesis na narração (morreu na cena sem registo? o
   sistema encerra; apareceu depois de morta? o sistema corrige o Mestre)
   mora em `aNemesisNaNarrativa` (src/motor/entrega-do-turno.js) desde a
   8.ª fatia da T1-A; o `aplicarResposta` chama-o e aplica o que ele diz. */

/* O que o Mestre lê sobre ela em TODO turno — viva ou morta. */
const infoNemesis = () => {
  const n = nemesisRef.current;
  if (!n || !n.nome) return "";
  if (n.status === "derrotada") {
    return `NÊMESIS ENCERRADA (fato do sistema): ${n.nome}, "${n.titulo}", está MORTA${n.comoMorreu ? ` — ${n.comoMorreu}` : ""}. Não a coloque em cena, não a faça agir nem enviar agentes, e não invente sucessores dela.`;
  }
  return resumoVilaoPrompt(n);
};

/* os efeitos que o App já sabe aplicar pelos seus próprios sistemas: o
   laço do herói com a pessoa (firmar, ao máximo, romper — npcs.js) e a
   relação com quem está no registo. A bolsa sai no clique, com o
   veredito antes. O resto (a luta, o teste, a missão, os dias, o tique)
   chega ao Narrador como fato, na linha da decisão, e é o motor de cada
   um que o faz acontecer na resposta. */
const aplicarEfeitosDoCoracao = (efeitos) => {
  let npcs = npcsRef.current || {};
  const chaveDe = (nome) => Object.keys(npcs).find((k) => k.toLowerCase() === String(nome || "").toLowerCase());
  let mudou = false;
  for (const e of (Array.isArray(efeitos) ? efeitos : [])) {
    try {
      if (!e) continue;
      if (e.tipo === "laco" && !e.com) {
        const k = chaveDe(e.nome);
        if (!k) continue;
        const npc = npcs[k];
        const tipoDe = (n) => (garantirLaco(n && n.laco) || {}).tipo;
        const forcaDe = (n) => (garantirLaco(n && n.laco) || {}).forca || 0;
        let novo = npc;
        if (e.delta === "rompe") novo = romperLaco(npc, diaRef.current);
        else if (e.delta === -1) novo = afrouxarLaco(npc);
        else if (e.delta === 1) novo = firmarLaco(npc, e.firma || tipoDe(npc) || "amizade", diaRef.current);
        else if (e.delta === "max") { let ant = -1; while (ant !== forcaDe(novo)) { ant = forcaDe(novo); novo = firmarLaco(novo, e.firma || tipoDe(novo) || "amizade", diaRef.current); } }
        if (novo !== npc) { npcs = { ...npcs, [k]: novo }; mudou = true; }
      } else if (e.tipo === "relacao" && e.com && e.valor) {
        const k = chaveDe(e.com);
        if (!k) continue;
        npcs = { ...npcs, [k]: { ...npcs[k], relacao: String(e.valor) } };
        mudou = true;
      }
    } catch (e2) { calou("um efeito do coração", e2); }
  }
  if (mudou) { npcsRef.current = npcs; setNpcs(npcs); }
};

const confirmarCoracao = (pauta) => {
  const pend = coracaoPendenteRef.current;
  coracaoPendenteRef.current = null;
  if (!pend || !pend.r) return;
  const r = pend.r;
  const nucleo = nucleoAgora();
  const elo = ((nucleo && nucleo.pessoas) || []).find((x) => x && x.papel === "elo") || null;
  const specs = elo ? sementesDoElo(nucleo, { dia: diaRef.current }) : [];
  const dela = (x) => !!(specs.length && x && x.dona === specs[0].dona && x.alvo === elo.nome);
  try {
    if (elo && specs.length && (pend.emCena || []).includes(elo.nome)) {
      let L = garantirLivro(promessasRef.current);
      if (!L.sementes.some(dela)) { for (const sp of specs) L = semear(L, sp).livro; promessasRef.current = L; }
    }
  } catch (e) { calou("as sementes do elo", e); }
  if (r.linha && !String(pauta || "").includes(r.linha)) return;
  coracaoRef.current = garantirCoracaoDoSave(r.coracao);
  /* E1 (o Narrador só narra): a figura que o arco pôs em cena tem nome
     (`inst.figura`, subtramas.js) — e, se a linha que a nomeia coube no
     texto, entra no registo, para o Narrador não a rebatizar depois. */
  try {
    const b = r.batida;
    const inst = b ? (subtramasAgora(nucleo) || []).find((i) => i && i.nome === b.nome && i.figura && i.figura.nome) : null;
    if (inst && r.linha && r.linha.includes(inst.figura.nome)) {
      const fig = inst.figura;
      const reg = npcsRef.current || {};
      if (!Object.keys(reg).some((k) => k.toLowerCase() === String(fig.nome).toLowerCase())) {
        const novo = { ...reg, [String(fig.nome).slice(0, 40)]: criarNPC(String(fig.nome).slice(0, 40), { papel: fig.papel || "", genero: fig.genero === "ela" ? "mulher" : "homem", local: cidadeAtualRef.current || "", ultimaVez: npcTurnoRef.current, conhecidoEm: diaRef.current }) };
        npcsRef.current = novo; setNpcs(novo);
      }
    }
  } catch (e) { calou("a figura do arco no registo", e); }
  if (r.quem) { const rt = coracaoRitmoRef.current || {}; coracaoRitmoRef.current = { ...rt, ultimas: { ...(rt.ultimas || {}), [r.quem]: pend.turno } }; }
  try { aplicarEfeitosDoCoracao(r.efeitos); } catch (e) { calou("os efeitos do coração", e); }
  try {
    const b = r.batida;
    if (elo && b && b.nome === elo.nome) {
      let L = garantirLivro(promessasRef.current);
      if ((b.tipo === "pistaA" || b.tipo === "pistaB") && specs[b.pista]) {
        const sm = L.sementes.find((x) => dela(x) && x.forma === specs[b.pista].forma && x.estado !== "paga" && x.estado !== "murcha");
        if (sm) L = regar(L, sm.id, { dia: diaRef.current, cena: elo.nome }).livro;
      } else if (b.tipo === "revelacao" || b.tipo === "corpo") {
        for (const sm of L.sementes.filter((x) => dela(x) && x.estado === "madura")) L = pagar(L, sm.id, { dia: diaRef.current }).livro;
      }
      promessasRef.current = L;
    }
  } catch (e) { calou("o Livro do coração", e); }
};

/* 9.ª sessão (v9.433): as bancas que estão NA CENA — na cidade, as de
   sempre; na estrada, só a carroça do ambulante (a cidade de partida ficou
   para trás); na masmorra aberta, nenhuma. É daqui que a pauta tira o
   preço e a frase compra. */
const bancasDaCena = () => {
  if (masmorraRef.current && !masmorraRef.current.encerrada) return [];
  const todas = Array.isArray(mercadoAqui) ? mercadoAqui : [];
  if (jornadaRef.current) return todas.filter((m) => m && m.tipo === "ambulante");
  return cidadeAtualRef.current ? todas : [];
};

/* ---------------- COMPRAR MANTIMENTO (v9.150) ----------------
   O preço é recalculado AQUI, e não lido do que a tela mostrou: a
   tela pode estar velha (o dia virou, a estação mudou, a pressão da
   praça andou) e cobrar o número antigo seria deixar o jogador
   comprar no preço de ontem. Quem decide o preço é sempre o mesmo
   lugar, no instante do gesto. */
const balcaoAqui = (cid = cidadeMercado) => balcaoDeMantimentos(cid, {
  dia: diaRef.current, pressoes: (mercadoRef.current || {}).pressoes || {},
  extra: fatorDeMercado((posturaRef.current || {}).postura, { vendendo: false }),
  temKit: garantirSuprimentos((personagemRef.current || personagem).suprimentos).kit,
});

/* DIPLOMACIA: propostas a potências vão para a ficção; o Mestre decide a
   resposta do líder e só registra o tratado firmado — os efeitos (renda,
   tributo) são calculados pelo app. */
/* ---------------- A DIPLOMACIA (v9.142) ----------------
   Esta era a última sala em que a IA decidia o que existe. O texto que ia
   ao Narrador dizia "A DECISÃO É DELE(A)" e mandava a IA escrever o
   tratado de volta no mundo. Todo o resto do projeto foi feito para tirar
